insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('dc000000-0000-0000-0000-000000000001', 'mrcp2', '7bb7f76b-1256-46d8-9a19-786810963cbf',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('dc000000-0000-0000-0000-000000000001', 'A', 'Add a regular low-dose benzodiazepine (e.g., diazepam) for long-term maintenance therapy', false, 'Ruled out because benzodiazepines are not recommended for long-term maintenance in panic disorder due to dependence risk, tolerance, and rebound anxiety on discontinuation; they are reserved for short-term crisis use only.', 1),
('dc000000-0000-0000-0000-000000000001', 'B', 'Switch to venlafaxine, titrating to a dose within the licensed range for panic disorder, while continuing CBT', true, 'Correct. Venlafaxine (an SNRI) is an appropriate second-line agent when an adequate SSRI trial (correct dose, sufficient duration, with concurrent CBT) has produced only partial response in panic disorder. Continuing psychological therapy alongside the medication switch maximises the chance of remission.', 2),
('dc000000-0000-0000-0000-000000000001', 'C', 'Stop sertraline and observe, as panic disorder is usually self-limiting without pharmacotherapy', false, 'Ruled out because untreated panic disorder with agoraphobia frequently becomes chronic and disabling; stopping treatment abruptly after partial response is inappropriate and risks relapse.', 3),
('dc000000-0000-0000-0000-000000000001', 'D', 'Increase sertraline beyond the licensed maximum dose before considering a change in drug class', false, 'Ruled out because sertraline is already at an adequate, guideline-recommended dose (150 mg is within range); exceeding licensed doses is not standard practice and does not reliably improve outcomes.', 4),
('dc000000-0000-0000-0000-000000000001', 'E', 'Refer for propranolol as first-line long-term pharmacotherapy instead of an antidepressant', false, 'Ruled out because beta-blockers only address peripheral somatic symptoms (tremor, palpitations) and have no proven efficacy for the core cognitive and anticipatory features of panic disorder; they are not a recommended first- or second-line treatment.', 5),
('dc000000-0000-0000-0000-000000000002', 'A', 'Continue sertraline at the same dose and add oral salt tablets to correct the sodium', false, 'Ruled out because continuing the causative drug while the mechanism (inappropriate water retention) persists will not correct hyponatraemia and risks worsening confusion and seizure risk; the causative agent should be stopped.', 1),
('dc000000-0000-0000-0000-000000000002', 'B', 'Give a rapid infusion of 3% hypertonic saline regardless of symptom severity', false, $x$Ruled out because hypertonic saline is reserved for severe, actively seizing or significantly symptomatic hyponatraemia with very close monitoring to avoid overly rapid correction and osmotic demyelination syndrome; this patient's presentation (confusion but no seizures) is managed initially with drug withdrawal and fluid restriction, with specialist input if severity increases.$x$, 2),
('dc000000-0000-0000-0000-000000000002', 'C', 'Increase sertraline dose, as the symptoms are more likely to represent worsening anxiety than a drug adverse effect', false, 'Ruled out because the biochemistry confirms hyponatraemia from SIADH, a recognised SSRI adverse effect, not a psychiatric symptom; increasing the causative drug would worsen the problem.', 3),
('dc000000-0000-0000-0000-000000000002', 'D', 'Switch immediately to a tricyclic antidepressant without addressing the current hyponatraemia', false, 'Ruled out because the acute electrolyte abnormality must be addressed first (stopping the causative drug, correcting sodium safely); tricyclics also carry their own separate risk profile and switching should be a later, considered decision, not an immediate substitute action.', 4),
('dc000000-0000-0000-0000-000000000002', 'E', 'Stop sertraline, restrict fluids, and manage as SSRI-induced SIADH with a plan to consider mirtazapine or an alternative agent with lower hyponatraemia risk if antidepressant therapy is required again', true, 'Correct. SSRIs are a recognised cause of the syndrome of inappropriate antidiuretic hormone secretion (SIADH), particularly in the first weeks of treatment and in older or female patients. The biochemical picture (hyponatraemia with inappropriately concentrated urine, normal renal and adrenal function) is classic for SIADH. Management is to stop the causative drug and restrict fluids (with more cautious correction if severe/symptomatic); mirtazapine has a comparatively lower reported association with SIADH and can be considered if an antidepressant is needed later.', 5),
('dc000000-0000-0000-0000-000000000003', 'A', 'Refer for cognitive behavioural therapy targeted at health anxiety, and agree with the patient and his GP a single coordinated care plan that limits further unnecessary investigation while explaining the diagnosis clearly', true, 'Correct. This presentation is consistent with illness anxiety disorder (health anxiety): persistent, disproportionate preoccupation with having a serious illness despite repeated negative investigations, with checking behaviours and functional impairment. The evidence-based treatment is CBT specifically targeted at health anxiety. A single coordinated care plan (ideally with one identified clinician/GP as gatekeeper) reduces reinforcing repeated investigation-seeking, which perpetuates the anxiety cycle rather than resolving it.', 1),
('dc000000-0000-0000-0000-000000000003', 'B', 'Arrange a further whole-body CT and PET scan to definitively exclude malignancy before considering any psychological input', false, 'Ruled out because further investigation in the absence of new clinical findings is not indicated, reinforces the anxiety-driven checking/reassurance-seeking cycle, and exposes the patient to unnecessary radiation without benefit; the priority is psychological management.', 2),
('dc000000-0000-0000-0000-000000000003', 'C', $x$Explain that his symptoms are 'all in his head' and discharge him from further follow-up$x$, false, 'Ruled out because this dismissive framing is inaccurate, damages the therapeutic relationship, and does not address the genuine distress and impairment health anxiety causes; ongoing coordinated care and psychological treatment are needed, not discharge.', 3),
('dc000000-0000-0000-0000-000000000003', 'D', 'Start a high-dose antipsychotic to manage what is likely to be an underlying delusional disorder', false, 'Ruled out because there are no psychotic features (no fixed, false, unshakeable belief maintained despite absolute proof to the contrary of delusional intensity, and the patient responds to reassurance to some degree) — this is health anxiety, not a psychotic illness, and antipsychotics are not indicated.', 4),
('dc000000-0000-0000-0000-000000000003', 'E', 'Refer urgently to oncology for a second specialist opinion given the number of presentations', false, 'Ruled out because repeated normal specialist investigations have already excluded organic pathology; further oncology referral without new clinical indication perpetuates rather than resolves the underlying problem.', 5),
('dc000000-0000-0000-0000-000000000004', 'A', 'Increase levetiracetam to a higher dose and add a second antiepileptic given ongoing episodes', false, 'Ruled out because video-EEG has not demonstrated epileptiform activity during typical events; continuing or escalating antiepileptic therapy is not indicated and exposes the patient to unnecessary medication risk without evidence of benefit.', 1),
('dc000000-0000-0000-0000-000000000004', 'B', 'Tell the patient the episodes are not real and that no further follow-up is required', false, $x$Ruled out because functional neurological disorder produces genuine, involuntary symptoms that cause real distress and disability; dismissing them as 'not real' is inaccurate, damages engagement, and denies the patient access to effective treatment.$x$, 2),
('dc000000-0000-0000-0000-000000000004', 'C', 'Stop the antiepileptic medication, explain the diagnosis of functional (dissociative) seizures sensitively using the video-EEG evidence, and refer for specialist psychological therapy (e.g., CBT-based or specialist FND physiotherapy programme)', true, 'Correct. Video-EEG-confirmed absence of epileptiform activity during typical episodes, combined with clinical features such as eye closure during the event (more typical of functional than epileptic seizures) and lack of response to antiepileptics, supports a diagnosis of functional neurological disorder (dissociative seizures). Management involves clear, sensitive communication of the diagnosis (ideally with the video-EEG evidence shown to the patient), stopping unnecessary antiepileptic drugs, and referral to specialist psychological therapy/FND-specific rehabilitation, which has the best evidence for improving outcomes.', 3),
('dc000000-0000-0000-0000-000000000004', 'D', 'Arrange for immediate psychiatric hospital admission under the Mental Health Act for treatment of the seizures', false, 'Ruled out because functional neurological disorder does not, by itself, meet criteria for detention under the Mental Health Act, and there is no indication here of risk requiring involuntary admission; outpatient specialist psychological/rehabilitation input is the appropriate route.', 4),
('dc000000-0000-0000-0000-000000000004', 'E', 'Repeat further prolonged video-EEG monitoring indefinitely until every possible episode type is captured before considering any diagnosis', false, 'Ruled out because three witnessed typical events without epileptiform correlation is sufficient for a confident functional (dissociative) seizure diagnosis in this clinical context; further prolonged monitoring delays appropriate treatment without added diagnostic value.', 5),
('dc000000-0000-0000-0000-000000000005', 'A', 'Order a repeat full-body MRI and inflammatory panel at this visit to reassure her, as requested', false, 'Ruled out because repeated investigation without new clinical indication perpetuates the cycle of transient reassurance followed by renewed anxiety and further requests, and does not address the underlying disorder.', 1),
('dc000000-0000-0000-0000-000000000005', 'B', 'Refer to a different specialist team each time she presents so that she receives a fresh assessment', false, 'Ruled out because fragmented care with multiple different clinicians increases inconsistent messaging, duplicate investigation, and patient anxiety; continuity with a single named clinician is the recommended approach.', 2),
('dc000000-0000-0000-0000-000000000005', 'C', 'Explain that her symptoms are entirely psychological in origin and that no further medical review is needed', false, 'Ruled out because this dismissive, binary framing is inaccurate (somatic symptom disorder involves genuinely distressing physical symptoms with excessive associated thoughts/behaviours, not fabricated symptoms) and would damage engagement; ongoing supportive medical review continues, focused differently.', 3),
('dc000000-0000-0000-0000-000000000005', 'D', 'Establish a single regular named clinician for ongoing review, avoid further investigation unless new objective clinical signs develop, and refer for a structured pain-management/CBT-based programme addressing the impact of symptoms on function', true, 'Correct. In somatic symptom disorder, repeated investigation provides only transient reassurance and reinforces symptom-focused behaviour, ultimately increasing anxiety and healthcare dependence. The evidence-based approach is continuity of care with a single trusted clinician, avoidance of unnecessary repeat testing unless new objective findings emerge, and a structured programme (CBT-based or multidisciplinary pain management) focused on improving function and quality of life rather than eliminating symptoms.', 4),
('dc000000-0000-0000-0000-000000000005', 'E', 'Start a strong opioid analgesic for symptom control while investigations continue', false, $x$Ruled out because opioids are not indicated for chronic pain in somatic symptom disorder, carry dependence risk, and 'investigations continuing' is precisely the pattern that should be interrupted in favour of a functional, non-investigative management approach.$x$, 5),
('dc000000-0000-0000-0000-000000000006', 'A', 'Single-session psychological debriefing delivered immediately after the incident to prevent PTSD developing', false, 'Ruled out because routine single-session psychological debriefing has not been shown to prevent PTSD and may in some studies worsen outcomes; it is not recommended practice, and in any case this patient already has established PTSD requiring active treatment now.', 1),
('dc000000-0000-0000-0000-000000000006', 'B', 'Long-term regular benzodiazepine therapy to control hyperarousal symptoms', false, 'Ruled out because benzodiazepines are not recommended in PTSD; they do not treat the core re-experiencing and avoidance symptoms, carry dependence risk, and some evidence suggests they may impair the effectiveness of trauma-focused psychological therapy.', 2),
('dc000000-0000-0000-0000-000000000006', 'C', 'Trauma-focused cognitive behavioural therapy (or EMDR) as first-line treatment', true, 'Correct. For PTSD, trauma-focused psychological therapies — trauma-focused CBT or eye movement desensitisation and reprocessing (EMDR) — are recommended as first-line treatment ahead of pharmacotherapy in adults, particularly for single-incident trauma. Medication (e.g., venlafaxine or an SSRI such as sertraline) is generally reserved for those who decline or do not have access to therapy, or as an adjunct in more severe/complex presentations.', 3),
('dc000000-0000-0000-0000-000000000006', 'D', 'Start high-dose antipsychotic medication as first-line monotherapy', false, 'Ruled out because antipsychotics are not first-line treatment for PTSD; they have a limited adjunctive role in specific circumstances (e.g., severe unresponsive symptoms with psychotic features) but are not appropriate initial monotherapy here.', 4),
('dc000000-0000-0000-0000-000000000006', 'E', 'Advise watchful waiting with no active treatment, as symptoms are expected to resolve spontaneously within a year', false, 'Ruled out because this patient has significant, functionally impairing symptoms at three months meeting criteria for PTSD; active treatment (trauma-focused therapy) should be offered now rather than a purely observational approach.', 5),
('dc000000-0000-0000-0000-000000000007', 'A', 'Stop all pharmacotherapy since OCD does not respond to medication and rely solely on further exposure and response prevention sessions', false, 'Ruled out because SSRIs (and clomipramine) have good evidence for efficacy in OCD; stopping pharmacotherapy entirely is not indicated when partial or no response has occurred, and combined treatment is more effective than psychological therapy alone in many patients.', 1),
('dc000000-0000-0000-0000-000000000007', 'B', 'Add a benzodiazepine for long-term daily use to control anxiety triggered by contamination fears', false, 'Ruled out because benzodiazepines are not indicated as maintenance treatment for OCD and do not address the underlying obsessive-compulsive symptoms; long-term use carries dependence risk.', 2),
('dc000000-0000-0000-0000-000000000007', 'C', 'Proceed directly to psychosurgery given treatment resistance', false, 'Ruled out because psychosurgery (e.g., deep brain stimulation/ablative procedures) is reserved for a small minority of severe, chronic, genuinely treatment-refractory OCD cases after multiple adequate trials of medication augmentation and intensive psychological therapy have failed — this patient has only had one adequate SSRI trial so far.', 3),
('dc000000-0000-0000-0000-000000000007', 'D', 'Switch to a different SSRI or consider clomipramine, continuing exposure and response prevention therapy', true, 'Correct. In OCD that has not responded adequately to a full, adequate trial of one SSRI (correct dose and duration) alongside exposure and response prevention (ERP), guidelines recommend trying an alternative SSRI or clomipramine (a tricyclic with potent serotonergic action, effective in OCD though requiring ECG monitoring given cardiotoxicity/QTc risk). ERP should continue in parallel, as combined pharmacological and psychological treatment produces the best outcomes.', 4),
('dc000000-0000-0000-0000-000000000007', 'E', 'Refer for antipsychotic monotherapy without continuing any SSRI or psychological therapy', false, 'Ruled out because antipsychotics have a role only as augmentation to an SSRI in treatment-resistant OCD, not as monotherapy, and psychological therapy (ERP) should continue rather than being discontinued.', 5),
('dc000000-0000-0000-0000-000000000008', 'A', 'Refer urgently for the requested rhinoplasty, as this will address the underlying concern', false, 'Ruled out because cosmetic surgery does not resolve body dysmorphic disorder; satisfaction is rarely achieved and new areas of preoccupation commonly emerge, so surgical referral is not appropriate management.', 1),
('dc000000-0000-0000-0000-000000000008', 'B', 'Reassure her that her nose looks normal and discharge with no further follow-up', false, 'Ruled out because reassurance alone is not effective in BDD (patients do not durably respond to reassurance about appearance) and this presentation, with significant functional impairment, warrants active psychiatric treatment, not discharge.', 2),
('dc000000-0000-0000-0000-000000000008', 'C', 'Start an antipsychotic as first-line monotherapy for the preoccupation', false, 'Ruled out because antipsychotics are not first-line treatment for BDD; SSRIs combined with CBT are the evidence-based first-line approach, with antipsychotic augmentation considered only in resistant cases with an SSRI already in place.', 3),
('dc000000-0000-0000-0000-000000000008', 'D', 'Advise strict avoidance of all mirrors as the primary therapeutic intervention', false, 'Ruled out because mirror avoidance alone is not an evidence-based treatment strategy for BDD (in fact, structured mirror-retraining is sometimes used within CBT); the primary interventions are SSRI pharmacotherapy and BDD-adapted CBT.', 4),
('dc000000-0000-0000-0000-000000000008', 'E', 'Advise against cosmetic surgery, explain the diagnosis of body dysmorphic disorder, and start an SSRI at a dose within the range used for OCD-spectrum disorders alongside CBT referral', true, 'Correct. Body dysmorphic disorder is treated with SSRIs (often at doses similar to those used in OCD) and CBT adapted for BDD, not with cosmetic intervention. Cosmetic/surgical procedures typically fail to relieve BDD symptoms and are frequently followed by new preoccupations or dissatisfaction; patients should be advised against pursuing surgery and directed towards evidence-based psychiatric treatment.', 5),
('dc000000-0000-0000-0000-000000000009', 'A', 'Continue both sertraline and tramadol at current doses since symptoms are likely to be simple opioid-related anxiety', false, 'Ruled out because the combination of hyperreflexia, clonus, autonomic instability and fever in a patient recently started on a serotonergic opioid while on an SSRI is classic for serotonin syndrome, not simple anxiety; continuing the causative drugs risks progression to severe, life-threatening toxicity.', 1),
('dc000000-0000-0000-0000-000000000009', 'B', 'Stop sertraline and tramadol immediately, give supportive care with IV fluids and benzodiazepines for agitation, and consider cyproheptadine if symptoms are moderate-to-severe or not settling', true, 'Correct. This is serotonin syndrome, precipitated by the interaction between an SSRI and tramadol (which also has serotonergic activity), characterised by neuromuscular hyperactivity (clonus, hyperreflexia, tremor), autonomic instability (tachycardia, fever) and agitation with clear limb findings. Management involves immediate cessation of all serotonergic agents, supportive care (IV fluids, cooling, benzodiazepines for agitation and to reduce muscle activity/hyperthermia risk), and the serotonin antagonist cyproheptadine for moderate-to-severe or persistent cases.', 2),
('dc000000-0000-0000-0000-000000000009', 'C', 'Start an antipsychotic such as haloperidol to sedate the agitation', false, 'Ruled out because antipsychotics are not first-line for the agitation of serotonin syndrome; benzodiazepines are preferred, and antipsychotics can complicate the picture (anticholinergic effects, and difficulty distinguishing from neuroleptic malignant syndrome) without addressing the underlying serotonergic excess.', 3),
('dc000000-0000-0000-0000-000000000009', 'D', 'Administer dantrolene as first-line treatment for this presentation', false, 'Ruled out because dantrolene is used for neuroleptic malignant syndrome and malignant hyperthermia (which involve muscle rigidity from a different mechanism); serotonin syndrome is primarily managed with removal of serotonergic drugs, benzodiazepines, and cyproheptadine if needed, not dantrolene.', 4),
('dc000000-0000-0000-0000-000000000009', 'E', 'Arrange outpatient psychiatric review in two weeks with no change to current medications', false, 'Ruled out because this is an acute, potentially life-threatening presentation (autonomic instability, hyperthermia, neuromuscular findings) requiring immediate cessation of the causative drugs and same-day medical management, not delayed outpatient follow-up.', 5),
('dc000000-0000-0000-0000-000000000010', 'A', $x$Convert to an equivalent dose of diazepam if not already on it (already on diazepam here) and taper the dose gradually over weeks to months, reducing by small increments with the patient's agreement, monitoring for withdrawal symptoms including seizure risk$x$, true, $x$Correct. After more than a decade of regular high-dose benzodiazepine use, abrupt cessation carries a significant risk of withdrawal seizures and severe rebound anxiety/autonomic instability. The recommended approach is a slow, gradual dose reduction (commonly using diazepam given its long half-life, which produces a smoother withdrawal course), individualised in pace to the patient's tolerance, sometimes over many months, with monitoring for withdrawal symptoms throughout.$x$, 1),
('dc000000-0000-0000-0000-000000000010', 'B', 'Stop diazepam abruptly today, as the risk of long-term cognitive impairment outweighs any withdrawal risk', false, 'Ruled out because abrupt cessation after long-term, high-dose benzodiazepine use carries a real risk of withdrawal seizures, severe rebound anxiety, and autonomic instability; discontinuation must be gradual, not abrupt.', 2),
('dc000000-0000-0000-0000-000000000010', 'C', 'Switch to a short-acting benzodiazepine such as lorazepam to make tapering easier', false, 'Ruled out because short-acting benzodiazepines produce more abrupt interdose withdrawal effects and are generally harder, not easier, to taper from; long-acting diazepam is preferred as the agent for gradual dose reduction.', 3),
('dc000000-0000-0000-0000-000000000010', 'D', 'Add a second benzodiazepine from a different subclass to help control anxiety during the taper', false, 'Ruled out because adding a further benzodiazepine increases dependence and sedation risk rather than facilitating safe discontinuation; the correct approach is gradual reduction of a single long-acting agent.', 4),
('dc000000-0000-0000-0000-000000000010', 'E', 'Refuse to taper and continue the same dose indefinitely, since long-term use is safe in patients over 60', false, 'Ruled out because long-term benzodiazepine use is not considered safe in older adults (falls, cognitive impairment, dependence) and the patient has expressed a clear wish and clinical rationale to discontinue; a supported gradual taper should be offered.', 5),
('dc000000-0000-0000-0000-000000000011', 'A', 'Conclude she lacks capacity because she has a diagnosis of dementia', false, $x$Ruled out because a diagnosis alone (the 'diagnostic threshold') is never sufficient to determine incapacity under the Mental Capacity Act; capacity must be assessed against the specific decision using the functional test, not inferred from diagnosis.$x$, 1),
('dc000000-0000-0000-0000-000000000011', 'B', 'Ask her next of kin to make the decision on her behalf, as she has dementia', false, 'Ruled out because in England and Wales, unlike some other jurisdictions, next of kin do not have automatic legal authority to consent to treatment on behalf of an adult; a formal capacity assessment for this specific decision must be undertaken first, and if she lacks capacity, a best interests decision is made by the treating team (informed by family views), not by family consent alone.', 2),
('dc000000-0000-0000-0000-000000000011', 'C', 'Defer any capacity assessment until she is fully recovered from sepsis, delaying the amputation decision', false, 'Ruled out because acute sepsis is a life-threatening emergency requiring a timely decision; capacity should be assessed now, in the context of her current state (acknowledging that acute illness may fluctuate and reversible causes of impaired capacity should be considered), rather than delaying urgent treatment decisions indefinitely.', 3),
('dc000000-0000-0000-0000-000000000011', 'D', 'Apply the Mental Capacity Act two-stage test specifically to the amputation decision: confirm an impairment of the mind/brain, then assess whether she can understand, retain, use/weigh, and communicate the specific information relevant to this decision', true, 'Correct. Capacity assessment under the Mental Capacity Act 2005 is decision-specific and time-specific. The first stage establishes whether there is an impairment or disturbance in functioning of the mind or brain (here, dementia). The second stage assesses the four functional abilities regarding the specific decision at hand (amputation): understanding the relevant information, retaining it long enough to make the decision, using or weighing it, and communicating the decision. Her inability to retain the information or weigh the consequences of refusing treatment, demonstrated here, is directly relevant to this specific decision, not a global judgement based on her diagnosis alone.', 4),
('dc000000-0000-0000-0000-000000000011', 'E', 'Assume capacity is present because she can state a clear preference to keep her leg', false, 'Ruled out because being able to express a preference is only one of the four functional elements; here she cannot retain information or demonstrate understanding of the consequences of refusal, which are also required to establish capacity for this decision.', 5),
('dc000000-0000-0000-0000-000000000012', 'A', 'Ask the two children to reach agreement between themselves and follow whichever decision they eventually agree on', false, 'Ruled out because responsibility for a best interests decision in the absence of a valid attorney or advance decision rests with the treating clinical team, not with family members reaching their own agreement; family views are one input into, not a substitute for, the clinical best interests process.', 1),
('dc000000-0000-0000-0000-000000000012', 'B', 'Hold a best interests meeting involving the treating team and both family members to consider his previously expressed wishes, values and beliefs, alongside clinical factors, with the final decision made by the responsible clinician applying the best interests checklist', true, $x$Correct. Where a patient lacks capacity and has no valid advance decision or attorney with relevant authority, treatment decisions are made in the patient's best interests under the Mental Capacity Act. This involves consulting those close to the patient (here, both children) about his previously expressed wishes, feelings, values and beliefs, but the final decision-making responsibility and accountability rests with the treating clinician(s), applying the best interests checklist (least restrictive option, patient's own likely wishes, and all relevant circumstances) — the decision is not simply whichever family member insists, nor deferred indefinitely due to family disagreement.$x$, 2),
('dc000000-0000-0000-0000-000000000012', 'C', 'Delay treatment until the Court of Protection can be consulted for every disagreement between family members', false, 'Ruled out because routine disagreement among family members does not require Court of Protection involvement; court referral is reserved for cases of genuine, serious, unresolvable dispute or particularly finely balanced/high-stakes decisions, and urgent treatment should not be delayed inappropriately while informal best-interests processes are followed.', 3),
('dc000000-0000-0000-0000-000000000012', 'D', 'Appoint an Independent Mental Capacity Advocate (IMCA) instead of consulting the family, since the family disagree', false, 'Ruled out because an IMCA is specifically for patients who have no family or friends appropriate to consult, not for cases where family exist but disagree; here the family should be consulted as part of the best interests process, not bypassed in favour of an IMCA.', 4),
('dc000000-0000-0000-0000-000000000012', 'E', 'Withhold all treatment since capacity is absent and no clear consensus exists', false, $x$Ruled out because withholding necessary treatment is not automatically in the patient's best interests; a best interests decision must still be actively reached (which may include treatment) using the checklist, rather than defaulting to non-treatment due to lack of family consensus.$x$, 5),
('dc000000-0000-0000-0000-000000000013', 'A', $x$Use the Mental Capacity Act to treat in his best interests (he lacks capacity due to delirium) and apply restraint/restriction proportionate to prevent harm, reserving the doctor's holding power (Section 5(2) MHA) only if a mental health-specific admission issue later arises$x$, true, $x$Correct. This man's inability to consent to leaving or to treatment stems from an acute confusional state (delirium) impairing his capacity — this is managed under the Mental Capacity Act, using best interests treatment decisions and proportionate restraint/restriction (which may itself need to be justified as a deprivation of liberty safeguard if prolonged) to keep him safe and treat the underlying UTI. Section 5(2) MHA (doctor's holding power) is a Mental Health Act tool intended for patients already admitted specifically for treatment of a mental disorder who wish to leave; it is not the primary framework for a physically unwell, delirious patient on a general medical ward whose issue is a physical illness causing transient incapacity, though in some circumstances it can still be used pragmatically — the MCA best interests route is the correct primary framework here.$x$, 1),
('dc000000-0000-0000-0000-000000000013', 'B', 'Allow him to self-discharge immediately, respecting his stated wish to go home', false, 'Ruled out because he currently lacks capacity to make this decision (due to delirium impairing retention and understanding), and allowing him to leave in this state poses a serious, foreseeable risk of harm from untreated sepsis; his stated wish cannot simply be honoured without a capacity assessment first.', 2),
('dc000000-0000-0000-0000-000000000013', 'C', 'Section him under Section 2 of the Mental Health Act for assessment of an underlying mental illness', false, 'Ruled out because Section 2 MHA is intended for assessment/treatment of mental disorder, and his presentation is due to delirium secondary to a treatable physical illness (UTI); the Mental Capacity Act, not the Mental Health Act, is the appropriate framework for managing incapacity arising from an acute physical medical cause.', 3),
('dc000000-0000-0000-0000-000000000013', 'D', $x$Wait until a psychiatrist is available before administering any treatment or preventing him leaving, even if this means several hours' delay$x$, false, 'Ruled out because urgent treatment of sepsis should not be delayed for psychiatric review when the situation can be appropriately managed under the Mental Capacity Act by the treating medical team using best interests principles and proportionate restraint; delaying antibiotics risks clinical deterioration.', 4),
('dc000000-0000-0000-0000-000000000013', 'E', 'Physically restrain him without any legal framework, relying on clinical judgement alone', false, 'Ruled out because any restriction of liberty or use of restraint must be justified and proportionate under a recognised legal framework (the Mental Capacity Act, including consideration of deprivation of liberty safeguards if restriction is prolonged/intense), not applied purely on ad hoc clinical judgement without that framework.', 5),
('dc000000-0000-0000-0000-000000000014', 'A', 'Detain under Section 2 of the Mental Health Act, as this is more appropriate for a first presentation requiring further diagnostic assessment', false, 'Ruled out because Section 2 is primarily for assessment (up to 28 days) where the diagnosis or treatment plan is not yet clear; here the diagnosis (severe psychotic depression) and the treatment need (urgent physical stabilisation and probable ECT) are already clear, making Section 3 (for treatment) the more appropriate route, particularly given the urgency.', 1),
('dc000000-0000-0000-0000-000000000014', 'B', 'Treat entirely under the Mental Capacity Act using best interests, as she lacks capacity due to her mental illness', false, 'Ruled out because where inpatient psychiatric treatment for mental disorder is required and the patient is objecting to admission, the Mental Health Act (not the Mental Capacity Act) is generally the appropriate framework, since the MCA does not authorise the kind of restrictive inpatient psychiatric treatment against objection that this situation requires; the interface rules point towards MHA use here.', 2),
('dc000000-0000-0000-0000-000000000014', 'C', 'Detain under Section 3 of the Mental Health Act for treatment of her mental disorder, as she requires admission and treatment (including possible ECT) for a diagnosed mental illness posing risk to her health, and is unwilling to be admitted informally', true, 'Correct. Section 3 MHA allows detention for treatment (up to 6 months initially) where a patient has a mental disorder of a nature or degree warranting hospital treatment, treatment is necessary for their health or safety or the protection of others, appropriate treatment is available, and the patient is unwilling to be admitted informally. This scenario — severe psychotic depression with life-threatening self-neglect requiring urgent treatment including possible ECT, in a patient refusing admission — is the paradigm indication for Section 3, since ongoing treatment (not just assessment) is clearly needed.', 3),
('dc000000-0000-0000-0000-000000000014', 'D', 'Ask her family to sign consent forms authorising her admission and treatment', false, 'Ruled out because family members do not have legal authority to consent to psychiatric admission or treatment on behalf of an adult in England and Wales; formal Mental Health Act or Mental Capacity Act processes must be followed.', 4),
('dc000000-0000-0000-0000-000000000014', 'E', 'Discharge her home with crisis team follow-up given her stated wish not to be admitted', false, 'Ruled out because she has a life-threatening presentation (severe dehydration and AKI from complete oral refusal driven by psychotic depression) requiring urgent inpatient treatment; her stated wish cannot be followed given she lacks capacity and the high immediate risk to her health.', 5),
('dc000000-0000-0000-0000-000000000015', 'A', 'No additional legal process is required as best interests treatment under the Mental Capacity Act alone is sufficient to justify any restriction', false, $x$Ruled out because ordinary best interests decision-making under the MCA covers treatment decisions but does not, by itself, authorise a deprivation of liberty; once restriction meets the 'acid test' (continuous supervision/control and not free to leave), a separate DoLS/LPS authorisation is required.$x$, 1),
('dc000000-0000-0000-0000-000000000015', 'B', 'Detain her under Section 2 of the Mental Health Act as the appropriate framework for restricting a confused patient on a medical ward', false, 'Ruled out because her need for restriction arises from dementia-related risk during treatment of a physical illness (pneumonia) on a general medical ward, not from a need for MHA-defined psychiatric treatment; DoLS/LPS under the MCA framework is the appropriate route for this kind of hospital-based deprivation of liberty in the context of physical healthcare, not Mental Health Act detention.', 2),
('dc000000-0000-0000-0000-000000000015', 'C', 'Physically restrain and sedate her as needed without formal authorisation since she lacks capacity to object meaningfully', false, 'Ruled out because lack of capacity does not remove the requirement for lawful authorisation of restriction amounting to a deprivation of liberty; appropriate statutory authorisation must still be sought.', 3),
('dc000000-0000-0000-0000-000000000015', 'D', 'Discharge her immediately to avoid any need for a deprivation of liberty authorisation', false, 'Ruled out because she has an acute, treatable illness (pneumonia) requiring inpatient care; discharging her purely to sidestep the need for a deprivation of liberty authorisation would not be in her best interests and is not an appropriate response to the legal requirement.', 4),
('dc000000-0000-0000-0000-000000000015', 'E', 'Recognise that continuous supervision and control plus lack of freedom to leave amounts to a deprivation of liberty, and apply for the appropriate statutory authorisation (Deprivation of Liberty Safeguards/Liberty Protection Safeguards as locally in force) alongside best interests treatment under the Mental Capacity Act', true, $x$Correct. Where a person who lacks capacity is under continuous supervision and control and is not free to leave, this constitutes a deprivation of liberty (the 'acid test'), which requires separate statutory authorisation beyond ordinary best interests treatment decisions — traditionally via the Deprivation of Liberty Safeguards (DoLS) framework in hospitals, with the Liberty Protection Safeguards (LPS) intended to extend and eventually replace this. Simply treating her in her best interests under the MCA is not sufficient once restriction reaches the level of a deprivation of liberty; the correct additional step is to seek the relevant authorisation.$x$, 5),
('dc000000-0000-0000-0000-000000000016', 'A', 'Transfuse blood immediately regardless of the advance decision, since his life is at immediate risk', false, 'Ruled out because a valid and applicable advance decision to refuse specific treatment (including life-sustaining treatment) is legally binding; overriding it because of the severity of risk is not lawful once validity and applicability are confirmed — clinicians who knowingly transfuse against a valid ADRT could be acting unlawfully.', 1),
('dc000000-0000-0000-0000-000000000016', 'B', 'Ask his wife to consent to transfusion on his behalf as his next of kin, overriding the advance decision', false, $x$Ruled out because next of kin have no legal authority in England and Wales to consent to or refuse treatment on an adult's behalf, and in any case cannot override a valid, applicable advance decision made by the patient himself while he had capacity.$x$, 2),
('dc000000-0000-0000-0000-000000000016', 'C', 'Disregard the advance decision because he is currently unconscious and cannot confirm it applies', false, 'Ruled out because the entire purpose of an advance decision is to apply in situations where the person has since lost capacity (such as unconsciousness) and cannot confirm their wishes at the time; provided validity and applicability criteria are met, it must be followed exactly in this scenario.', 3),
('dc000000-0000-0000-0000-000000000016', 'D', 'Seek an emergency Court of Protection order before making any transfusion decision', false, 'Ruled out because where an advance decision is clearly valid and applicable to the situation at hand, no court order is required — the document itself is legally determinative; court involvement is reserved for genuine uncertainty or dispute about validity/applicability, which is not present here given the explicit, specific wording.', 4),
('dc000000-0000-0000-0000-000000000016', 'E', $x$Withhold blood and blood products in line with the valid and applicable advance decision, treating haemorrhagic shock with all other appropriate measures (endoscopic haemostasis, non-blood volume expanders, cell salvage if acceptable to the patient's stated wishes)$x$, true, 'Correct. A valid and applicable advance decision to refuse treatment (ADRT) is legally binding under the Mental Capacity Act, even if refusing life-sustaining treatment, provided it was made by a person with capacity, is specific to the circumstances that have arisen, and has not been withdrawn. Here the document is signed, witnessed, made with capacity, and explicitly covers this exact clinical circumstance (life-threatening haemorrhage from his known diagnosis) — it is valid and applicable, and clinicians are legally obliged to respect it despite the life-threatening consequences, while continuing all other appropriate non-blood treatment.', 5),
('dc000000-0000-0000-0000-000000000017', 'A', 'Delay surgery until a SOAD certificate can be obtained, even though this risks perforation and sepsis', false, 'Ruled out because in a genuine surgical emergency threatening life or serious deterioration, urgent treatment provisions (Section 62 MHA where relevant to mental disorder treatment, and MCA best interests/emergency treatment principles for the physical condition) allow treatment to proceed without delay; awaiting non-urgent procedural safeguards while risking perforation is not appropriate.', 1),
('dc000000-0000-0000-0000-000000000017', 'B', 'Refuse to treat the appendicitis because she is detained under the Mental Health Act and this only covers treatment for mental disorder', false, 'Ruled out because detention under the MHA does not preclude treatment of unrelated physical conditions; physical health treatment in a patient lacking capacity is provided under the Mental Capacity Act (best interests, including emergency treatment provisions), and her psychiatric detention/treatment continues in parallel.', 2),
('dc000000-0000-0000-0000-000000000017', 'C', 'Proceed under Section 62 of the Mental Health Act, which permits urgent treatment to be given without the normal Part 4 consent/second opinion safeguards where treatment is immediately necessary to save life or prevent serious deterioration, alongside standard Mental Capacity Act best interests principles for the surgical decision itself', true, $x$Correct. Section 62 MHA provides for urgent treatment to proceed without the usual Part 4 consent-to-treatment safeguards (such as SOAD certification) when treatment is immediately necessary to save the patient's life, to prevent serious deterioration, to alleviate serious suffering, or (with additional conditions) to prevent violence/danger — it removes the delay imposed by normally-required second opinion procedures in a genuine emergency. In practice, the underlying capacity-based decision for the physical treatment itself (appendicectomy) is also assessed and given under the Mental Capacity Act's best interests framework, since Part 4 MHA consent-to-treatment provisions apply to treatment for mental disorder, and treatment of an unrelated physical condition like appendicitis in a person lacking capacity is separately governed by the MCA; Section 62 is relevant here because her detention status and any relevant medication/treatment for her mental disorder that is time-critical can also proceed urgently under this provision without waiting for a SOAD.$x$, 3),
('dc000000-0000-0000-0000-000000000017', 'D', 'Ask her family to provide consent for the emergency surgery on her behalf', false, $x$Ruled out because family members do not have legal authority to consent to treatment for an adult in England and Wales; the decision is made under the Mental Capacity Act's best interests and emergency treatment principles by the treating clinicians.$x$, 4),
('dc000000-0000-0000-0000-000000000017', 'E', 'Apply for a new Section 2 assessment before proceeding with surgery', false, 'Ruled out because she is already detained under Section 3 for her mental disorder; the acute surgical issue is an unrelated physical health emergency requiring urgent treatment under Mental Capacity Act principles, not a fresh Mental Health Act assessment.', 5),
('dc000000-0000-0000-0000-000000000018', 'A', 'Conclude he permanently lacks capacity because he was confused in the afternoon, and make all future decisions for him under best interests without ever reassessing', false, 'Ruled out because capacity must be reassessed for each significant decision, and a single afternoon episode of confusion during known fluctuating delirium does not permanently determine incapacity; ongoing reassessment is required, especially once the underlying delirium (from pneumonia) is treated.', 1),
('dc000000-0000-0000-0000-000000000018', 'B', 'Ignore the morning assessment and only use the afternoon assessment because it was more recent', false, 'Ruled out because recency alone does not determine which assessment is valid; the presence of documented capacity during a lucid period is a legitimate basis for decision-making, and simply favouring the most recent assessment ignores the well-recognised fluctuating nature of delirium.', 2),
('dc000000-0000-0000-0000-000000000018', 'C', 'Avoid making any decision at all until the delirium has completely resolved, even if this significantly delays starting necessary anticoagulation', false, 'Ruled out because where decisions have shown he retains capacity to be understood clearly and consistently during lucid periods and are appropriately documented, unnecessary delay is not required; while waiting for full resolution is sometimes reasonable for complex non-urgent decisions, using and documenting a genuine lucid-interval capacity assessment is an appropriate and standard approach rather than blanket avoidance.', 3),
('dc000000-0000-0000-0000-000000000018', 'D', 'Recognise that capacity can fluctuate with delirium, and where possible time significant decisions (or confirm and document them) during his lucid periods, reassessing before the decision is finally acted upon if his condition changes', true, $x$Correct. Capacity is decision- and time-specific, and delirium characteristically produces fluctuating capacity. Where a decision is not immediately time-critical, good practice is to assess and, where possible, time or confirm significant decisions during periods when the patient demonstrates capacity (lucid intervals), documenting this clearly, and to reassess if there is any concern the patient's state has changed before the decision is acted upon or if new information needs to be given.$x$, 4),
('dc000000-0000-0000-0000-000000000018', 'E', 'Ask a family member to make the decision since his capacity is inconsistent', false, 'Ruled out because family members do not have automatic legal authority to make treatment decisions for an adult; where capacity fluctuates, the correct approach is careful, timed reassessment of the patient himself, not simply transferring decision-making to family.', 5),
('dc000000-0000-0000-0000-000000000019', 'A', 'Respect her wishes fully and withhold feeding, as this is patient autonomy', false, 'Ruled out because her ability to weigh information about the risk of refusing feeding is judged to be impaired specifically by her eating disorder (a recognised feature of severe anorexia nervosa), meaning this is not a free, capacitous refusal but a manifestation of the illness itself, and she faces imminent life-threatening risk (severe bradycardia, hypokalaemia) requiring urgent treatment.', 1),
('dc000000-0000-0000-0000-000000000019', 'B', 'Use the Mental Health Act (e.g., Section 3, or relevant provisions for a minor) to detain and treat her, since nasogastric feeding here is treatment for the physical manifestations/consequences of her mental disorder (anorexia nervosa) and she is refusing life-saving treatment due to that disorder', true, $x$Correct. Case law and established practice recognise that artificial feeding for anorexia nervosa, including the physical complications of severe malnutrition, can be provided as 'treatment for mental disorder' under the Mental Health Act, because the physical state is a direct manifestation of the underlying psychiatric illness distorting her perception and decision-making about food/weight. Where a patient with anorexia nervosa lacks capacity to make this decision because of the eating disorder itself and treatment is necessary and urgent, detention and treatment under the MHA (with appropriate safeguards, involving age-appropriate considerations given she is 17) is the recognised route, rather than relying solely on the Mental Capacity Act.$x$, 2),
('dc000000-0000-0000-0000-000000000019', 'C', 'Rely solely on parental consent to authorise nasogastric feeding without any capacity assessment or Mental Health Act consideration', false, 'Ruled out because for a 17-year-old with a severe psychiatric disorder actively refusing treatment, relying purely on parental consent without formal capacity/best-interests or Mental Health Act processes is legally insufficient and does not provide the same safeguards or authority for potentially restrictive treatment such as forced feeding; formal legal frameworks should be used.', 3),
('dc000000-0000-0000-0000-000000000019', 'D', 'Discharge her for outpatient dietetic follow-up only, given her expressed wishes', false, 'Ruled out because her physiological parameters (severe bradycardia, profound hypokalaemia, very low BMI) indicate an immediately life-threatening state requiring urgent inpatient medical stabilisation and feeding, not outpatient management.', 4),
('dc000000-0000-0000-0000-000000000019', 'E', 'Wait for her to turn 18 before any compulsory treatment can be considered', false, 'Ruled out because the Mental Health Act (and Mental Capacity Act, with modifications) can apply to minors, and urgent, life-threatening risk cannot be deferred until she reaches adulthood; treatment decisions must be made now.', 5),
('dc000000-0000-0000-0000-000000000020', 'A', 'Recognise he is absent without leave (AWOL) from his Section 17 leave; the detention under Section 3 continues, and he can be taken into custody and returned to hospital by staff or the police within the statutory time limits that apply', true, 'Correct. A patient detained under the Mental Health Act who fails to return from, or absconds during, authorised Section 17 leave is considered absent without leave (AWOL). His underlying detention (Section 3) does not lapse; he remains liable to be recalled, and staff or police have the power to take him into custody and return him to hospital, subject to the statutory time limits for taking such action after which the authority to return him under that section may expire and the detaining authority must consider next steps (e.g., whether the section itself has lapsed).', 1),
('dc000000-0000-0000-0000-000000000020', 'B', 'Conclude that his Section 3 detention automatically ends once he leaves the leave escort, and no action is required', false, 'Ruled out because absconding from Section 17 leave does not automatically discharge the underlying Mental Health Act detention; he remains liable to be returned to hospital as an AWOL patient, subject to statutory time limits.', 2),
('dc000000-0000-0000-0000-000000000020', 'C', 'Treat this purely as a police missing-persons matter with no mental health team or hospital involvement', false, 'Ruled out because the hospital/responsible clinician retains responsibility for a detained patient who is AWOL, must inform the relevant authorities appropriately, and remains involved in his care and eventual return, working alongside police as needed rather than handing the matter over entirely.', 3),
('dc000000-0000-0000-0000-000000000020', 'D', 'Wait indefinitely with no defined time limit before considering whether his section has lapsed', false, 'Ruled out because there are defined statutory time limits within which an AWOL detained patient can be taken into custody and returned under the same authority; beyond this, the detaining authority must specifically consider whether the section has lapsed and what further action (e.g., readmission processes) is required, rather than an indefinite, undefined wait.', 4),
('dc000000-0000-0000-0000-000000000020', 'E', 'Discharge him from his Section 3 detention because Section 17 leave implies he is no longer unwell enough to need detention', false, 'Ruled out because granting leave under Section 17 is a clinical decision about the appropriate setting for ongoing treatment and does not indicate the patient no longer meets criteria for detention; discharge should be a separate, considered clinical decision, not an automatic consequence of leave or absconding.', 5),
('dc000000-0000-0000-0000-000000000021', 'A', 'Continue lithium at a reduced dose while monitoring levels daily', false, 'Ruled out because with severe toxicity (level 2.8 mmol/L) and significant clinical features (confusion, ataxia), lithium must be stopped immediately, not merely dose-reduced; continuing any dose in this context risks further deterioration.', 1),
('dc000000-0000-0000-0000-000000000021', 'B', 'Restrict fluids to reduce further lithium absorption', false, 'Ruled out because fluid restriction would worsen the underlying dehydration driving the toxicity and reduce renal lithium clearance further; volume repletion with IV fluids, not restriction, is required.', 2),
('dc000000-0000-0000-0000-000000000021', 'C', 'Give oral sodium polystyrene sulfonate (a potassium binder) to enhance lithium elimination', false, 'Ruled out because this agent is used for hyperkalaemia and has no established role in enhancing lithium elimination; the recognised interventions are fluid resuscitation, stopping precipitants, and haemodialysis in severe cases.', 3),
('dc000000-0000-0000-0000-000000000021', 'D', 'Stop lithium, ibuprofen and bendroflumethiazide immediately, give IV isotonic saline for volume repletion and to promote lithium excretion, and urgently discuss with renal/toxicology for consideration of haemodialysis given the severity of toxicity and renal impairment', true, 'Correct. This is severe lithium toxicity precipitated by dehydration (gastroenteritis), an NSAID (ibuprofen, which reduces renal lithium clearance) and a thiazide diuretic (which increases proximal tubular sodium and lithium reabsorption) — a classic combination of precipitants. With a level of 2.8 mmol/L, significant neurotoxicity (confusion, ataxia, coarse tremor) and renal impairment, this is severe toxicity requiring immediate cessation of the causative and contributing drugs, IV fluid resuscitation, and urgent renal/toxicology discussion for haemodialysis, which is indicated in severe toxicity with renal impairment or significant neurological features, as lithium is small and dialysable.', 4),
('dc000000-0000-0000-0000-000000000021', 'E', 'Manage as an outpatient with a lithium level recheck in one week', false, 'Ruled out because this presentation (marked neurotoxicity, significantly elevated level, renal impairment) constitutes a medical emergency requiring immediate inpatient assessment and treatment, not outpatient deferral.', 5),
('dc000000-0000-0000-0000-000000000022', 'A', 'Switch to a third different SSRI at standard dose and continue as before with no other changes', false, 'Ruled out because after two adequate, different-class-mechanism SSRI trials have failed, simply switching to another SSRI has a lower likelihood of success than an augmentation strategy or switching to a different class/mechanism (e.g., venlafaxine, mirtazapine) plus augmentation consideration.', 1),
('dc000000-0000-0000-0000-000000000022', 'B', 'Recommend permanent discontinuation of all antidepressant treatment as further trials are futile', false, 'Ruled out because treatment-resistant depression is not untreatable; augmentation strategies, different-class antidepressants, and other interventions (e.g., ECT in more severe or urgent cases) have good evidence of benefit and should be actively pursued, not abandoned.', 2),
('dc000000-0000-0000-0000-000000000022', 'C', 'Consider augmentation of the current antidepressant with lithium (or an atypical antipsychotic such as aripiprazole/quetiapine), with appropriate monitoring, rather than a further simple antidepressant switch alone', true, 'Correct. In treatment-resistant depression (inadequate response to at least two adequate antidepressant trials), evidence-based augmentation strategies include adding lithium (with dose titration to a therapeutic level and monitoring of renal/thyroid function and levels) or an atypical antipsychotic such as aripiprazole or quetiapine to the existing antidepressant, rather than continuing to cycle through antidepressant monotherapy switches alone, which has diminishing returns after two failed trials.', 3),
('dc000000-0000-0000-0000-000000000022', 'D', 'Start an MAOI immediately without any washout period from the current SSRI', false, 'Ruled out because switching directly from an SSRI to an MAOI without an adequate washout period risks serotonin syndrome; MAOIs may be considered later in resistant depression but require careful, guideline-directed switching with washout periods, not immediate co-administration.', 4),
('dc000000-0000-0000-0000-000000000022', 'E', 'Refer for immediate ECT without first considering pharmacological augmentation, as this is now the standard next step for any non-response', false, 'Ruled out because ECT is generally reserved for severe, treatment-resistant depression with specific features (e.g., psychotic features, catatonia, high suicide risk, or failure of multiple adequate trials including augmentation), not as the automatic next step after only two failed antidepressant trials in a patient who is not acutely at high risk; pharmacological augmentation is the appropriate next step here.', 5),
('dc000000-0000-0000-0000-000000000023', 'A', 'Confirm the diagnosis of catatonia (supported by the positive lorazepam challenge), continue regular benzodiazepine treatment, and arrange urgent electroconvulsive therapy given the severity, physical risk, and depressive catatonia if response to benzodiazepines is incomplete or too slow', true, 'Correct. This presentation (mutism, waxy flexibility, fixed posturing, marked improvement with a lorazepam challenge) is classic catatonia, here in the context of severe depression. First-line treatment is a benzodiazepine (typically lorazepam), often at escalating doses, but given the severity here (life-threatening dehydration, malignant features developing), and depressive catatonia responding well to it, ECT is the definitive and highly effective treatment, particularly if benzodiazepine response is incomplete, too slow given her physical deterioration, or if features suggestive of malignant catatonia emerge; urgent psychiatric and physical health management should proceed in parallel.', 1),
('dc000000-0000-0000-0000-000000000023', 'B', 'Start a first-generation antipsychotic to sedate her agitation', false, 'Ruled out because antipsychotics, particularly high-potency first-generation agents, can worsen catatonia and precipitate neuroleptic malignant syndrome in catatonic patients; they are generally avoided as initial treatment for catatonia.', 2),
('dc000000-0000-0000-0000-000000000023', 'C', 'Conclude this is simple severe depression not catatonia, since the lorazepam response was only temporary', false, 'Ruled out because a positive (even temporary) response to a lorazepam challenge is a recognised diagnostic feature supporting catatonia, not evidence against it; the temporary nature of response to a single test dose is expected, and definitive treatment (continued benzodiazepine and/or ECT) is what is required next, not exclusion of the diagnosis.', 3),
('dc000000-0000-0000-0000-000000000023', 'D', 'Manage conservatively with reassurance and observation only, given no specific treatment is required for catatonia', false, 'Ruled out because catatonia is a serious condition with risk of severe physical complications (dehydration, venous thromboembolism, malnutrition) and, without treatment, potential progression to malignant catatonia; active treatment (benzodiazepine, ECT) is required, not passive observation.', 4),
('dc000000-0000-0000-0000-000000000023', 'E', 'Withhold all treatment until formal psychiatric sectioning under the Mental Health Act is completed', false, 'Ruled out because urgent treatment of catatonia (a life-threatening condition given her dehydration and lack of oral intake) should not be delayed pending legal processes; where treatment is urgently needed and she lacks capacity, appropriate legal frameworks (which can include urgent provisions) should run in parallel with, not before, starting necessary treatment.', 5),
('dc000000-0000-0000-0000-000000000024', 'A', 'Start an SSRI antidepressant to help stabilise his mood', false, 'Ruled out because antidepressants are not indicated in acute mania and can precipitate further mood elevation or a switch into a more severe manic or mixed state; they have no role in this acute presentation.', 1),
('dc000000-0000-0000-0000-000000000024', 'B', 'Restart lithium and add an antipsychotic (e.g., olanzapine or risperidone) for more rapid control of acute manic symptoms while lithium levels are re-established', true, 'Correct. Acute mania is managed with an antipsychotic (which has a faster onset of action than lithium alone) either as monotherapy or in combination with a mood stabiliser; in a patient who has recently stopped an effective mood stabiliser (lithium), restarting it alongside an antipsychotic for rapid symptom control is appropriate first-line management, given his known good prior response to lithium.', 2),
('dc000000-0000-0000-0000-000000000024', 'C', 'Reassure and observe without any medication change, as this will likely resolve spontaneously within days', false, 'Ruled out because acute mania, especially with grandiosity, impulsivity (spending savings) and severe sleep disruption, carries significant risk of harm (financial, social, physical exhaustion) and requires active treatment, not passive observation.', 3),
('dc000000-0000-0000-0000-000000000024', 'D', 'Start a benzodiazepine as sole long-term treatment for the manic episode', false, 'Ruled out because while benzodiazepines can be useful short-term adjuncts for agitation/insomnia in acute mania, they are not an effective definitive treatment for the underlying manic episode; an antipsychotic and/or mood stabiliser is required.', 4),
('dc000000-0000-0000-0000-000000000024', 'E', 'Advise him to resume lithium alone at his previous dose and review again in six weeks', false, 'Ruled out because lithium alone has a slower onset of therapeutic action than an antipsychotic, and given the current severity and risk of this acute manic episode, more rapid symptom control (via antipsychotic, alongside restarting lithium) is needed rather than a lithium-only strategy with a lengthy review interval.', 5),
('dc000000-0000-0000-0000-000000000025', 'A', $x$Manage as an outpatient with weekly community follow-up given this is likely simple postnatal 'baby blues'$x$, false, 'Ruled out because baby blues is a mild, self-limiting low mood typically resolving within two weeks without psychotic features; this presentation, with psychosis, rapid escalation, and risk-related paranoid ideas, is a psychiatric emergency requiring urgent inpatient care, not outpatient management.', 1),
('dc000000-0000-0000-0000-000000000025', 'B', 'Reassure her partner that this will resolve on its own and no specific treatment is required', false, 'Ruled out because postpartum psychosis is a serious, rapidly evolving emergency with risk of harm to mother and baby if untreated; active urgent psychiatric treatment is required, not reassurance and non-intervention.', 2),
('dc000000-0000-0000-0000-000000000025', 'C', 'Separate mother and baby completely and indefinitely as a blanket safety measure without individualised risk assessment', false, 'Ruled out because management should involve individualised, ongoing risk assessment with appropriate supervised contact where safe (ideally facilitated by admission to a specialist mother and baby unit), rather than an automatic, indefinite blanket separation, which can also harm bonding and maternal mental health if not clinically necessary.', 3),
('dc000000-0000-0000-0000-000000000025', 'D', 'Start only psychological therapy (CBT) without any pharmacological treatment given she is breastfeeding', false, 'Ruled out because postpartum psychosis is a severe, rapidly progressive psychiatric emergency requiring prompt pharmacological treatment (antipsychotic/mood stabiliser); psychological therapy alone is inadequate for this acuity, and breastfeeding compatibility can be addressed by selecting appropriate medications with specialist perinatal psychiatry input rather than withholding necessary treatment.', 4),
('dc000000-0000-0000-0000-000000000025', 'E', 'Treat as a psychiatric emergency with urgent admission to a specialist mother and baby unit, initiating antipsychotic (and/or mood stabiliser) treatment with close monitoring of mother-infant safety and risk', true, $x$Correct. This presentation — rapid onset within the first two weeks postpartum, fluctuating mood and psychotic symptoms, disorganisation and agitation — is classic for postpartum (puerperal) psychosis, a psychiatric emergency with risk to both mother and infant. Management requires urgent admission, ideally to a specialist mother and baby unit enabling ongoing bonding under safe supervision, prompt antipsychotic (often alongside a mood stabiliser given the frequent bipolar-spectrum nature of the illness) treatment, and careful risk assessment given the described paranoid ideas involving the baby's safety.$x$, 5),
('dc000000-0000-0000-0000-000000000026', 'A', 'Reassure him that these symptoms indicate his depression is relapsing and increase the dose of paroxetine substantially above his previous dose', false, 'Ruled out because the timing (within days of abrupt cessation) and symptom pattern (dizziness, sensory disturbance, irritability) are characteristic of discontinuation syndrome, not depressive relapse, which typically develops more gradually over weeks; the correct response is to restart at the previous effective dose and taper slowly, not to substantially increase the dose.', 1),
('dc000000-0000-0000-0000-000000000026', 'B', 'Advise him that no medication is needed and the symptoms will resolve without any intervention within a day', false, 'Ruled out because although discontinuation symptoms can be self-limiting over one to two weeks, restarting and then tapering the antidepressant is the recommended approach to relieve symptoms and prevent recurrence, rather than leaving him to tolerate ongoing symptoms unnecessarily.', 2),
('dc000000-0000-0000-0000-000000000026', 'C', 'Restart paroxetine at the previous effective dose to relieve symptoms, then taper the dose gradually over several weeks rather than stopping abruptly again', true, $x$Correct. This presentation (dizziness, 'electric shock' sensations, nausea, irritability, vivid dreams, arising within days of abrupt cessation) is classic antidepressant discontinuation syndrome, particularly associated with shorter half-life SSRIs such as paroxetine. Management is to restart the antidepressant to relieve symptoms, then withdraw it via a slow, gradual taper rather than abrupt discontinuation, to avoid recurrence of these symptoms.$x$, 3),
('dc000000-0000-0000-0000-000000000026', 'D', 'Switch immediately to an MAOI without any washout period to control symptoms', false, 'Ruled out because switching to an MAOI requires an adequate washout period after an SSRI to avoid serotonin syndrome, and this is not an appropriate response to simple discontinuation symptoms in any case; restarting the original agent and tapering is the correct approach.', 4),
('dc000000-0000-0000-0000-000000000026', 'E', 'Start a benzodiazepine as the primary treatment for these symptoms', false, 'Ruled out because benzodiazepines do not address the underlying cause (SSRI discontinuation) and are not the recommended treatment; restarting and gradually tapering the antidepressant is the appropriate management.', 5),
('dc000000-0000-0000-0000-000000000027', 'A', 'Continue sodium valproate unchanged throughout pregnancy since she is currently stable', false, 'Ruled out because continuing valproate through pregnancy exposes the fetus to a high risk of major malformations and neurodevelopmental harm; this is not an acceptable default given a safer alternative approach exists, and her current stability does not offset this teratogenic risk.', 1),
('dc000000-0000-0000-0000-000000000027', 'B', 'Advise switching away from sodium valproate given its high teratogenic risk (neural tube defects, neurodevelopmental impairment) and plan a gradual, carefully monitored change to a safer alternative (e.g., certain antipsychotics used for prophylaxis) with specialist perinatal psychiatry input, avoiding abrupt cessation that risks relapse', true, 'Correct. Sodium valproate carries a high risk of major congenital malformations (including neural tube defects) and long-term neurodevelopmental impairment when taken during pregnancy, and is contraindicated in women who could become pregnant unless strict criteria are met; on confirmed pregnancy, the priority is a carefully planned, gradual switch to a safer alternative under specialist (perinatal psychiatry/obstetric) guidance, balancing teratogenic risk against the substantial risk of relapse from abrupt medication cessation, which itself carries risks to mother and pregnancy.', 2),
('dc000000-0000-0000-0000-000000000027', 'C', 'Stop sodium valproate abruptly today with no replacement medication', false, 'Ruled out because abrupt cessation of an effective mood stabiliser carries a high risk of prompt relapse into mania or depression, which itself poses risks to both mother and pregnancy; any change should be a gradual, planned switch to an alternative, not abrupt stopping without replacement.', 3),
('dc000000-0000-0000-0000-000000000027', 'D', 'Recommend terminating the pregnancy immediately due to the current valproate exposure', false, $x$Ruled out because this is a decision entirely for the patient herself with full, balanced information and specialist counselling (including on the actual level of risk from six weeks' exposure and alternative management going forward), not something to be recommended directly by the clinician as the default course of action.$x$, 4),
('dc000000-0000-0000-0000-000000000027', 'E', 'Add lithium to her current valproate regimen rather than switching, to provide additional mood stability during pregnancy', false, $x$Ruled out because this adds a second agent with its own teratogenic considerations (lithium is associated with a small increased risk of cardiac malformations, particularly Ebstein's anomaly) on top of continued valproate exposure, rather than addressing the priority of removing the higher-risk valproate through a planned switch.$x$, 5),
('dc000000-0000-0000-0000-000000000028', 'A', 'Continue sertraline and simply increase the dose to better control her current depressive symptoms', false, 'Ruled out because antidepressant monotherapy is inappropriate in bipolar disorder, particularly with a rapid-cycling course, as it risks further destabilising mood and increasing cycling frequency rather than providing a stable, longer-term solution.', 1),
('dc000000-0000-0000-0000-000000000028', 'B', 'Add a second antidepressant from a different class to sertraline for augmentation of her depressive symptoms', false, 'Ruled out because combining antidepressants in bipolar disorder (particularly with a rapid-cycling pattern) is not the appropriate strategy; the priority is establishing effective mood-stabilising treatment rather than escalating antidepressant therapy.', 2),
('dc000000-0000-0000-0000-000000000028', 'C', 'Reassure her that this cycling pattern is expected and requires no change to her current sertraline monotherapy', false, 'Ruled out because rapid cycling on antidepressant monotherapy is a recognised, undesirable pattern requiring a change in treatment strategy (introduction of an appropriate mood stabiliser and cessation of antidepressant monotherapy), not reassurance without intervention.', 3),
('dc000000-0000-0000-0000-000000000028', 'D', 'Refer for ECT as first-line treatment for rapid-cycling bipolar disorder', false, 'Ruled out because ECT is not first-line for rapid-cycling bipolar disorder; the priority is optimising mood-stabilising pharmacotherapy and stopping inappropriate antidepressant monotherapy, with ECT reserved for specific severe or treatment-resistant circumstances.', 4),
('dc000000-0000-0000-0000-000000000028', 'E', 'Stop antidepressant monotherapy and start (or optimise) a mood stabiliser such as lithium or sodium valproate (where appropriate/not contraindicated) as the primary treatment, given a rapid-cycling course', true, 'Correct. Four or more mood episodes within a twelve-month period defines rapid-cycling bipolar disorder. Antidepressant monotherapy is not appropriate in bipolar disorder, as it can worsen cycling frequency or precipitate hypomanic/manic switches; the correct approach is to stop antidepressant monotherapy and establish an effective mood stabiliser (e.g., lithium, or valproate where not contraindicated by factors such as childbearing potential) as primary long-term treatment for a rapid-cycling course.', 5),
('dc000000-0000-0000-0000-000000000029', 'A', 'Stop sertraline immediately, arrange urgent psychiatric assessment given the high suicide risk associated with mixed states, and consider starting an antipsychotic and/or mood stabiliser rather than any antidepressant', true, 'Correct. This is a mixed affective episode (simultaneous depressive symptoms including suicidality, and manic/hypomanic features such as pressured speech, agitation and insomnia) — a recognised high-risk presentation for suicide given the combination of low mood/hopelessness with the energy and impulsivity of mania. Antidepressant monotherapy is inappropriate and potentially dangerous in mixed states (it can worsen manic/agitated symptoms and does not address the picture appropriately); the priority is to stop the antidepressant, urgently assess risk, and treat with an antipsychotic and/or mood stabiliser under psychiatric guidance.', 1),
('dc000000-0000-0000-0000-000000000029', 'B', 'Continue sertraline and increase the dose to treat the prominent depressive and suicidal symptoms more aggressively', false, 'Ruled out because antidepressants are inappropriate and potentially harmful in mixed affective states, risking worsening of the agitated/manic component and not addressing the specific elevated suicide risk of this presentation; the antidepressant should be stopped, not increased.', 2),
('dc000000-0000-0000-0000-000000000029', 'C', 'Discharge with routine GP follow-up in two weeks given he is currently on treatment for depression', false, 'Ruled out because this presentation carries a high, immediate suicide risk (mixed features are strongly associated with increased suicide risk) requiring urgent same-day psychiatric assessment, not routine delayed follow-up.', 3),
('dc000000-0000-0000-0000-000000000029', 'D', 'Add a benzodiazepine as the sole additional treatment while continuing sertraline unchanged', false, 'Ruled out because while a benzodiazepine may have a short-term adjunctive role for agitation/insomnia, the antidepressant itself is inappropriate in this mixed state and should be stopped, with definitive treatment being an antipsychotic and/or mood stabiliser under urgent psychiatric assessment, not benzodiazepine addition alone.', 4),
('dc000000-0000-0000-0000-000000000029', 'E', 'Advise he simply needs more sleep and review again in a week with no medication changes or urgent referral', false, 'Ruled out because this significantly understates the acuity and risk of a mixed affective state with suicidal ideation, which requires urgent psychiatric assessment and immediate medication review, not a passive week-long wait.', 5),
('dc000000-0000-0000-0000-000000000030', 'A', 'Long-term high-dose benzodiazepine therapy to reduce anxiety associated with relapse', false, 'Ruled out because benzodiazepines have no established evidence for reducing suicide risk in recurrent mood disorders, carry dependence risk with long-term use, and are not an appropriate long-term relapse-prevention or suicide-risk-reduction strategy.', 1),
('dc000000-0000-0000-0000-000000000030', 'B', 'Permanent discontinuation of all pharmacological treatment in favour of psychological therapy alone', false, 'Ruled out because this patient has a clear pattern of relapse whenever medication is withdrawn; given his high risk (recurrent severe episodes, prior serious suicide attempts), discontinuing all pharmacotherapy is not appropriate, and lithium augmentation alongside continued antidepressant and psychological therapy has stronger evidence.', 2),
('dc000000-0000-0000-0000-000000000030', 'C', 'A third different SSRI trial alone, as this has the best evidence for suicide risk reduction', false, 'Ruled out because simply cycling through further antidepressant monotherapy trials has not addressed his repeated relapse pattern, and no antidepressant class has evidence for suicide-risk reduction as strong and specific as lithium in recurrent mood disorders.', 3),
('dc000000-0000-0000-0000-000000000030', 'D', 'Long-term lithium augmentation added to his antidepressant, which has the strongest evidence among mood-stabilising/augmentation agents for reducing suicide risk in recurrent mood disorders', true, 'Correct. Lithium has the strongest evidence base of any psychotropic medication for reducing suicide risk and suicide-related mortality in patients with recurrent mood disorders, independent of its general mood-stabilising/antidepressant-augmenting effects. In a patient with recurrent severe depressive relapses and a significant suicide attempt history, long-term lithium augmentation of his antidepressant is a well-evidenced strategy to reduce future relapse and specifically suicide risk, alongside regular monitoring (levels, renal and thyroid function).', 4),
('dc000000-0000-0000-0000-000000000030', 'E', 'Long-term antipsychotic monotherapy without any mood stabiliser or continued antidepressant', false, 'Ruled out because antipsychotic monotherapy is not the appropriate long-term strategy for recurrent unipolar depression with a strong relapsing pattern, and lacks the specific evidence base for suicide risk reduction that lithium has in this context.', 5),
('dc000000-0000-0000-0000-000000000031', 'A', 'Continue clozapine at the same dose since the patient is asymptomatic and feels well', false, 'Ruled out because clozapine-induced agranulocytosis can develop and progress without symptoms initially; the mandatory monitoring protocol requires action based on the blood count itself, not symptom status, and continuing clozapine in the face of a significant neutrophil drop risks progression to severe, life-threatening agranulocytosis.', 1),
('dc000000-0000-0000-0000-000000000031', 'B', 'Stop clozapine immediately, repeat the full blood count urgently, and manage according to the clozapine haematological monitoring protocol (amber/red result) with close monitoring for evolving agranulocytosis', true, 'Correct. A significant drop in neutrophil count during clozapine treatment, even without symptoms, requires immediate action under the mandatory haematological monitoring protocol. A neutrophil count in this range (below 1.5 x10^9/L) meets criteria requiring clozapine to be stopped and increased monitoring frequency, given the risk of clozapine-induced agranulocytosis, which can progress rapidly and is potentially fatal if untreated; the patient must be monitored closely (daily or as per protocol) until the count recovers or agranulocytosis is confirmed/excluded, with haematology input as needed.', 2),
('dc000000-0000-0000-0000-000000000031', 'C', 'Reduce the clozapine dose by half and recheck the blood count in one month', false, 'Ruled out because dose reduction alone is not the appropriate response to a significant neutropenia on clozapine; the protocol requires stopping the drug and more frequent monitoring, not simply a lower dose with delayed rechecking, given the risk of rapid progression.', 3),
('dc000000-0000-0000-0000-000000000031', 'D', 'Switch immediately to a different antipsychotic without stopping clozapine first or urgent blood monitoring', false, 'Ruled out because the immediate priority is stopping clozapine and urgent, frequent blood monitoring per protocol; while an alternative antipsychotic will likely be needed given clozapine cannot usually be restarted after significant neutropenia, this should follow the correct emergency monitoring pathway rather than skip urgent action.', 4),
('dc000000-0000-0000-0000-000000000031', 'E', 'Delay any action until the next scheduled routine monitoring blood test in four weeks', false, 'Ruled out because a significant drop in neutrophil count requires an immediate, not delayed, response given the risk of rapidly progressive agranulocytosis; routine scheduled intervals are for standard ongoing monitoring, not for managing an already abnormal result.', 5),
('dc000000-0000-0000-0000-000000000032', 'A', 'Continue the depot antipsychotic since it cannot be immediately reversed and instead treat only the fever with paracetamol', false, 'Ruled out because although a depot cannot be physically removed, the priority is stopping any further antipsychotic dosing, providing full supportive/critical care management, and specific treatment as needed; treating fever with paracetamol alone grossly under-treats this life-threatening emergency.', 1),
('dc000000-0000-0000-0000-000000000032', 'B', 'Give a further dose of a different antipsychotic to sedate his agitation and confusion', false, 'Ruled out because administering any further antipsychotic in the context of active or suspected NMS is dangerous and can worsen the syndrome; antipsychotics should be avoided until NMS has fully resolved.', 2),
('dc000000-0000-0000-0000-000000000032', 'C', 'Manage as simple agitation with a benzodiazepine alone and no other intervention or investigation', false, 'Ruled out because this significantly understates the acuity and specific pathology present (fever, rigidity, elevated CK, autonomic instability) which requires full recognition and treatment of NMS as a medical emergency, not just benzodiazepine sedation.', 3),
('dc000000-0000-0000-0000-000000000032', 'D', 'Stop the antipsychotic, provide aggressive supportive care (IV fluids, cooling, cardiovascular monitoring), and consider dantrolene and/or bromocriptine in a critical care setting given the severity', true, 'Correct. This presentation (fever, lead-pipe muscle rigidity, autonomic instability, markedly elevated CK, confusion, in a patient on an antipsychotic) is classic neuroleptic malignant syndrome (NMS), a medical emergency. Management requires immediate cessation of the antipsychotic, aggressive supportive care (IV fluids for hydration and to protect renal function from rhabdomyolysis, active cooling, cardiovascular monitoring) typically in a high-dependency/critical care setting, with specific pharmacological treatment (dantrolene for severe rigidity/hyperthermia, and/or bromocriptine as a dopamine agonist) considered in more severe cases.', 4),
('dc000000-0000-0000-0000-000000000032', 'E', 'Start selective serotonin reuptake inhibitor therapy to manage his confusion and agitation', false, 'Ruled out because an SSRI has no role in treating NMS and this scenario shows no features suggesting serotonin syndrome (rigidity here is lead-pipe/generalised as expected in NMS, developing over days on an established antipsychotic, rather than the clonus/hyperreflexia and rapid onset typical of serotonin syndrome); introducing a new serotonergic agent is inappropriate.', 5),
('dc000000-0000-0000-0000-000000000033', 'A', 'Continue clozapine at the same dose and simply monitor troponin weekly', false, 'Ruled out because with a clinical and biochemical picture strongly suggestive of myocarditis, continuing the causative drug risks progression to severe, potentially fatal cardiac injury; clozapine must be stopped immediately, not continued with passive monitoring.', 1),
('dc000000-0000-0000-0000-000000000033', 'B', 'Reduce the clozapine dose by 50% and reassess symptoms in one week', false, 'Ruled out because suspected myocarditis in the early clozapine titration period requires immediate cessation of the drug, not dose reduction, given the risk of rapid progression to severe cardiac compromise.', 2),
('dc000000-0000-0000-0000-000000000033', 'C', 'Attribute the symptoms to simple anxiety related to starting a new medication and provide reassurance only', false, 'Ruled out because the combination of tachycardia, chest pain, markedly elevated troponin and CRP in the classic early time-window for clozapine-induced myocarditis is a recognised, serious adverse drug reaction requiring urgent action, not attribution to anxiety alone.', 3),
('dc000000-0000-0000-0000-000000000033', 'D', 'Arrange non-urgent outpatient cardiology follow-up in six weeks while continuing clozapine as normal', false, 'Ruled out because this presentation requires urgent, same-day assessment and immediate clozapine cessation given the risk of rapidly progressive myocarditis; non-urgent delayed follow-up while continuing the causative drug is inappropriate and dangerous.', 4),
('dc000000-0000-0000-0000-000000000033', 'E', 'Stop clozapine immediately and urgently refer for cardiology assessment, given the clinical and biochemical picture strongly suggestive of clozapine-induced myocarditis, particularly given the timing within the first weeks of treatment', true, 'Correct. Clozapine-induced myocarditis characteristically occurs within the first six to eight weeks of treatment (most commonly the first month), presenting with tachycardia, chest pain, breathlessness, elevated troponin and inflammatory markers (CRP), sometimes with ECG changes. It is a potentially life-threatening adverse effect requiring immediate clozapine cessation and urgent cardiology assessment (echocardiography, further cardiac workup) given the risk of progression to fulminant myocarditis and cardiomyopathy if unrecognised and clozapine continued.', 5),
('dc000000-0000-0000-0000-000000000034', 'A', 'Avoid IV haloperidol given the already prolonged QTc, correct any reversible contributing electrolyte abnormalities, and consider an alternative agent with continuous cardiac monitoring if antipsychotic treatment remains necessary', true, 'Correct. Haloperidol, particularly given intravenously, carries a significant risk of further QTc prolongation and torsades de pointes, and is relatively contraindicated when the baseline QTc is already prolonged (typically defined as greater than 450-470 ms depending on threshold used). The appropriate approach is to avoid IV haloperidol in this context, correct reversible contributors to QTc prolongation (e.g., hypokalaemia, hypomagnesaemia, common after alcohol withdrawal), and if antipsychotic treatment is still required, use with caution, at the lowest effective dose, and with continuous cardiac monitoring, potentially involving cardiology input for the safest choice of agent.', 1),
('dc000000-0000-0000-0000-000000000034', 'B', 'Proceed with IV haloperidol at the usual dose regardless of the baseline ECG findings', false, 'Ruled out because giving IV haloperidol with an already prolonged baseline QTc significantly increases the risk of torsades de pointes and sudden cardiac death; the ECG finding should directly change management, not be disregarded.', 2),
('dc000000-0000-0000-0000-000000000034', 'C', 'Withhold all antipsychotic treatment and manage severe agitation with physical restraint alone', false, 'Ruled out because physical restraint alone is not appropriate ongoing management for severe agitation and psychosis, and does not address the underlying clinical need; a safer pharmacological approach with appropriate monitoring should be used rather than reliance on restraint.', 3),
('dc000000-0000-0000-0000-000000000034', 'D', 'Increase the haloperidol dose further to achieve faster sedation given the severity of agitation', false, 'Ruled out because increasing the dose of a QTc-prolonging drug in a patient who already has a prolonged QTc further increases arrhythmia risk; this is the opposite of the appropriate cautious approach required here.', 4),
('dc000000-0000-0000-0000-000000000034', 'E', 'Give the haloperidol orally instead of IV, as oral administration carries no QTc prolongation risk', false, 'Ruled out because oral haloperidol still carries a dose-dependent QTc prolongation risk, albeit generally considered lower than the IV route; the correct approach is to avoid or minimise use of a QTc-prolonging antipsychotic altogether given the baseline prolongation, with monitoring, rather than simply changing the route while still using the same drug.', 5),
('dc000000-0000-0000-0000-000000000035', 'A', 'Delay any treatment for several months to confirm the diagnosis is not transient before starting an antipsychotic', false, $x$Ruled out because early intervention significantly improves outcomes in first-episode psychosis, and unnecessary delay in starting treatment is associated with worse prognosis (longer duration of untreated psychosis is a recognised poor prognostic factor); prompt assessment and treatment initiation is recommended, not a prolonged 'wait and see' period.$x$, 1),
('dc000000-0000-0000-0000-000000000035', 'B', 'Start a high dose of a first-generation typical antipsychotic without considering side-effect profile, as this is most effective for first presentations', false, 'Ruled out because first-generation antipsychotics are not preferred as automatic first choice due to a higher burden of extrapyramidal side effects, which is a particular consideration for a young patient early in what may be a long treatment course; low-dose atypical agents with careful side-effect consideration are generally preferred initially.', 2),
('dc000000-0000-0000-0000-000000000035', 'C', $x$Refer urgently to an early intervention in psychosis service for prompt assessment and initiation of a low-dose atypical antipsychotic, chosen with consideration of the individual's side-effect risk profile, alongside psychosocial support$x$, true, 'Correct. First-episode psychosis should be managed through prompt referral to a specialist early intervention in psychosis (EIP) service, which improves long-term outcomes through early, coordinated pharmacological and psychosocial intervention. Antipsychotic choice in a young patient should specifically consider the side-effect profile (e.g., metabolic risk with olanzapine, extrapyramidal effects with higher-potency agents, prolactin effects) given the long treatment horizon typically ahead, alongside family psychoeducation and psychological therapy.', 3),
('dc000000-0000-0000-0000-000000000035', 'D', 'Manage exclusively with CBT and no antipsychotic medication, as medication is not required in first-episode psychosis', false, 'Ruled out because antipsychotic medication, alongside psychological therapy, is part of standard evidence-based management for first-episode psychosis with significant symptoms and functional decline; psychological therapy alone is not the standard first-line approach here.', 4),
('dc000000-0000-0000-0000-000000000035', 'E', 'Admit compulsorily under the Mental Health Act as the default management for any first-episode psychosis presentation', false, 'Ruled out because compulsory admission is not automatic for first-episode psychosis; many patients can be managed through early intervention services in the community or via voluntary admission, with compulsory detention reserved for situations meeting specific MHA criteria (e.g., significant risk, lack of engagement with necessary treatment).', 5),
('dc000000-0000-0000-0000-000000000036', 'A', 'Try a third standard antipsychotic before considering clozapine, as clozapine should be reserved as a last resort after multiple further trials', false, 'Ruled out because guidelines define treatment resistance after two adequate trials (not three or more), and clozapine should be offered once this threshold is met rather than delaying further through additional standard antipsychotic trials, which have a low likelihood of success in genuinely treatment-resistant illness.', 1),
('dc000000-0000-0000-0000-000000000036', 'B', 'Add a second standard antipsychotic to risperidone as combination therapy rather than considering clozapine', false, 'Ruled out because antipsychotic polypharmacy (combining two standard agents) has limited evidence of added efficacy and increased side-effect burden compared with a trial of clozapine, which has the strongest evidence specifically for treatment-resistant schizophrenia.', 2),
('dc000000-0000-0000-0000-000000000036', 'C', 'Refer for ECT as the next step rather than considering clozapine', false, 'Ruled out because clozapine, not ECT, is the recommended next step for treatment-resistant schizophrenia after two adequate antipsychotic trials; ECT has a more limited, specific role in schizophrenia (e.g., for catatonia or in combination with clozapine in certain resistant cases), not as the standard next step here.', 3),
('dc000000-0000-0000-0000-000000000036', 'D', 'Initiate clozapine, as she meets criteria for treatment-resistant schizophrenia following two adequate trials of different antipsychotics with confirmed adherence and inadequate response', true, 'Correct. Treatment-resistant schizophrenia is defined as an inadequate response to at least two different antipsychotics, given at an adequate dose for an adequate duration (typically at least 6-8 weeks), with confirmed adherence. Clozapine is the recommended treatment for this group, as it has superior efficacy in treatment-resistant illness compared with switching between other antipsychotics, and initiation should not be unnecessarily delayed once criteria are met, given the mandatory monitoring requirements can be established in parallel.', 4),
('dc000000-0000-0000-0000-000000000036', 'E', 'Increase the risperidone dose substantially beyond standard therapeutic range before considering any other option', false, 'Ruled out because increasing beyond the standard therapeutic range does not reliably improve efficacy and increases side-effect risk (including extrapyramidal effects and hyperprolactinaemia); it does not substitute for moving to clozapine once treatment-resistance criteria are met with confirmed adequate adherence.', 5),
('dc000000-0000-0000-0000-000000000037', 'A', 'Continue risperidone unchanged and reassure her that these symptoms are unrelated to her medication', false, 'Ruled out because risperidone is a well-recognised cause of significant hyperprolactinaemia, and this temporal and symptomatic picture (amenorrhoea, galactorrhoea, elevated prolactin on this medication, normal pituitary imaging) strongly supports a drug-induced cause requiring active management, not reassurance alone.', 1),
('dc000000-0000-0000-0000-000000000037', 'B', 'Start bromocriptine while continuing risperidone at the same dose as the primary management strategy', false, $x$Ruled out because while dopamine agonists can lower prolactin, they carry a theoretical risk of worsening psychosis by counteracting the antipsychotic's mechanism of action; the preferred approach is switching to (or augmenting with) a prolactin-sparing antipsychotic such as aripiprazole rather than adding a dopamine agonist to an unchanged prolactin-raising antipsychotic regimen.$x$, 2),
('dc000000-0000-0000-0000-000000000037', 'C', 'Switch to a prolactin-sparing antipsychotic such as aripiprazole (which can also be used as an adjunct to lower prolactin from another antipsychotic), with monitoring of prolactin levels and symptoms after the switch', true, 'Correct. Risperidone is strongly associated with dose-dependent hyperprolactinaemia due to its potent dopamine D2 receptor blockade, including in the pituitary, causing symptoms such as amenorrhoea, galactorrhoea and sexual dysfunction. With a normal pituitary MRI excluding a prolactinoma, the elevated prolactin is attributed to the antipsychotic. Management involves switching to a prolactin-sparing agent such as aripiprazole (a partial dopamine agonist), which can also be used adjunctively to lower prolactin levels caused by another antipsychotic if switching entirely is not desired, with follow-up monitoring of prolactin and symptom resolution.', 3),
('dc000000-0000-0000-0000-000000000037', 'D', 'Refer for a pituitary biopsy given the markedly elevated prolactin level', false, 'Ruled out because pituitary imaging has already been performed and is normal, excluding a prolactinoma as the cause; invasive biopsy is not indicated when the clinical picture and normal imaging support a straightforward medication-induced cause.', 4),
('dc000000-0000-0000-0000-000000000037', 'E', 'Stop all antipsychotic treatment permanently given the severity of this side effect', false, 'Ruled out because stopping antipsychotic treatment entirely risks relapse of her underlying schizophrenia; the appropriate approach is switching to an alternative, prolactin-sparing antipsychotic rather than complete cessation of antipsychotic treatment.', 5),
('dc000000-0000-0000-0000-000000000038', 'A', 'Increase the dose of haloperidol to further sedate the patient and settle the muscle spasm', false, 'Ruled out because increasing the dose of the causative antipsychotic will worsen, not improve, an acute dystonic reaction; the correct treatment is an anticholinergic agent, and the causative drug/dose should be reviewed.', 1),
('dc000000-0000-0000-0000-000000000038', 'B', 'Reassure the patient that this will resolve without treatment within 24 hours and provide no active intervention', false, 'Ruled out because acute dystonic reactions are painful and distressing and respond rapidly to anticholinergic treatment; withholding treatment and waiting is not appropriate when an effective, fast-acting remedy is available.', 2),
('dc000000-0000-0000-0000-000000000038', 'C', 'Administer dantrolene as the first-line treatment for this presentation', false, 'Ruled out because dantrolene is used for neuroleptic malignant syndrome and malignant hyperthermia, not for a simple acute dystonic reaction, which is a distinct, much more common and rapidly reversible extrapyramidal side effect treated with anticholinergics.', 3),
('dc000000-0000-0000-0000-000000000038', 'D', 'Stop haloperidol completely and start an SSRI instead to manage his agitation', false, 'Ruled out because an SSRI has no role in managing acute agitation/psychosis or in treating a dystonic reaction; the immediate priority is anticholinergic treatment for the dystonia, with subsequent review of antipsychotic choice/dose as a separate consideration.', 4),
('dc000000-0000-0000-0000-000000000038', 'E', 'Give IM or IV procyclidine (an anticholinergic) for rapid relief of the acute dystonic reaction', true, 'Correct. This presentation (acute onset of sustained, painful muscle contraction causing abnormal posturing such as torticollis, occurring within hours of starting or increasing a dose of a high-potency antipsychotic like haloperidol) is a classic acute dystonic reaction. It is treated promptly with an anticholinergic agent such as IM or IV procyclidine, which typically produces rapid symptomatic relief.', 5),
('dc000000-0000-0000-0000-000000000039', 'A', 'Start haloperidol at a standard antipsychotic dose as first-line treatment for his hallucinations', false, 'Ruled out because haloperidol (a high-potency typical antipsychotic) carries a particularly high risk of severe, life-threatening neuroleptic sensitivity reactions in dementia with Lewy bodies and should be avoided; this is a specific, important safety point distinguishing DLB management from other causes of agitation.', 1),
('dc000000-0000-0000-0000-000000000039', 'B', 'Avoid antipsychotics where possible, first addressing reversible precipitants (e.g., infection, pain, medication review) and using non-pharmacological measures, given the high risk of severe, potentially life-threatening neuroleptic sensitivity reactions in dementia with Lewy bodies', true, $x$Correct. Patients with dementia with Lewy bodies (and Parkinson's disease dementia) have a well-recognised, high risk of severe neuroleptic sensitivity reactions to antipsychotics, particularly typical/first-generation agents like haloperidol, which can cause acute, severe parkinsonism, autonomic instability, impaired consciousness and even death. The priority is identifying and treating reversible precipitants of agitation/hallucinations (e.g., infection, pain, medication changes, environmental factors) and non-pharmacological management; if an antipsychotic is genuinely unavoidable, a low-dose atypical agent with the least antidopaminergic/extrapyramidal liability (e.g., quetiapine) is used with extreme caution and specialist input, not a typical antipsychotic like haloperidol.$x$, 2),
('dc000000-0000-0000-0000-000000000039', 'C', 'Increase the dose of any existing antiparkinsonian medication to control the hallucinations', false, 'Ruled out because increasing dopaminergic antiparkinsonian medication would likely worsen, not improve, psychotic symptoms/hallucinations in this context; the priority is addressing reversible precipitants and considering the safest possible symptomatic approach if needed, not increasing dopaminergic drugs.', 3),
('dc000000-0000-0000-0000-000000000039', 'D', 'Use physical restraint as the primary management strategy instead of considering any medication', false, 'Ruled out because physical restraint is not an appropriate primary management strategy; the correct approach is identifying and treating reversible precipitants and using non-pharmacological de-escalation techniques, reserving cautious pharmacological options only if genuinely necessary.', 4),
('dc000000-0000-0000-0000-000000000039', 'E', 'Prescribe a benzodiazepine as first-line treatment for his hallucinations and agitation', false, 'Ruled out because benzodiazepines are not first-line for hallucinations in dementia with Lewy bodies and can worsen confusion and falls risk in older patients with dementia; the priority remains identifying reversible causes and using cautious, non-pharmacological approaches first.', 5),
('dc000000-0000-0000-0000-000000000040', 'A', 'Recognise this as delirium (given the acute onset, fluctuating course, and inattention in the context of infection, hypoxia and post-operative state) and prioritise identifying and treating the underlying reversible medical causes, using non-pharmacological measures first', true, 'Correct. The acute onset, fluctuating course (worse at night), disorientation and inattention, occurring post-operatively in an older patient with evidence of infection and hypoxia, is characteristic of delirium rather than a primary psychotic illness (which would not typically present with this fluctuating, acute-onset pattern with clear precipitating physical illness in someone with no prior psychiatric history). Management prioritises identifying and treating the underlying causes (treating the UTI, correcting hypoxia, reviewing medications, ensuring adequate hydration/pain control), with non-pharmacological reorientation strategies (consistent staff, lighting, involving family, minimising ward moves) as first-line; antipsychotics are reserved for severe distress/agitation posing risk, used cautiously at low dose.', 1),
('dc000000-0000-0000-0000-000000000040', 'B', 'Diagnose new-onset late-life schizophrenia and start regular antipsychotic treatment as the primary intervention', false, 'Ruled out because this presentation is far more consistent with delirium secondary to identifiable acute physical illness (infection, hypoxia, post-surgical state) than with new-onset primary psychotic illness; the priority is treating the underlying medical causes, not committing to a schizophrenia diagnosis and regular antipsychotic treatment.', 2),
('dc000000-0000-0000-0000-000000000040', 'C', 'Reassure staff that hallucinations are a normal part of ageing and require no further assessment', false, 'Ruled out because new visual hallucinations with fluctuating attention in this context are not a normal ageing change; they indicate delirium requiring urgent identification and treatment of underlying causes, not reassurance without assessment.', 3),
('dc000000-0000-0000-0000-000000000040', 'D', 'Start regular high-dose antipsychotic medication immediately as the first step in management, before assessing for reversible causes', false, 'Ruled out because the priority in delirium is identifying and treating reversible underlying causes and using non-pharmacological measures first; antipsychotics are not the first step and, if used at all, are reserved for severe agitation/distress at the lowest effective dose for the shortest time, given increased risks in older patients.', 4),
('dc000000-0000-0000-0000-000000000040', 'E', 'Arrange an urgent EEG and lumbar puncture before considering any treatment of the urinary tract infection or hypoxia', false, 'Ruled out because with a clear, identifiable precipitant already evident (UTI, hypoxia, post-operative state) in a classic delirium presentation, the priority is treating these reversible causes; invasive further investigation is not the immediate priority and should only be considered if the picture does not fit typical delirium or fails to improve with treatment of the identified causes.', 5),
('dc000000-0000-0000-0000-000000000041', 'A', 'Give IV glucose first to correct likely hypoglycaemia, followed by thiamine once glucose has been administered', false, $x$Ruled out because giving glucose before thiamine replacement in a potentially thiamine-deficient patient (as is common in chronic heavy alcohol use) can precipitate or worsen Wernicke's encephalopathy; thiamine must be given first, or at least concurrently, never after glucose administration.$x$, 1),
('dc000000-0000-0000-0000-000000000041', 'B', 'Manage with supportive care and reassurance alone, avoiding sedative medication given his agitation and risk of respiratory depression', false, 'Ruled out because delirium tremens carries significant mortality risk if untreated with an appropriate benzodiazepine regimen; withholding sedative treatment entirely in confirmed delirium tremens is dangerous, not protective.', 2),
('dc000000-0000-0000-0000-000000000041', 'C', 'Start an antipsychotic such as haloperidol as first-line monotherapy for the agitation and hallucinations', false, 'Ruled out because antipsychotics are not first-line for delirium tremens (they do not treat the underlying withdrawal state, may lower seizure threshold, and do not address the autonomic instability); benzodiazepines are the evidence-based first-line treatment, with antipsychotics used cautiously only as an adjunct if psychotic symptoms are severe and unresponsive to adequate benzodiazepine dosing.', 3),
('dc000000-0000-0000-0000-000000000041', 'D', 'Start a symptom-triggered or fixed-dose reducing regimen of chlordiazepoxide, give IV thiamine (Pabrinex) before any glucose-containing fluids, and manage on a monitored bed given the severity of delirium tremens', true, $x$Correct. This presentation (tremor, autonomic hyperactivity, visual hallucinations, agitation, disorientation, emerging around 48-72 hours after the last drink) is delirium tremens, a medical emergency with significant mortality if untreated. Management is with a benzodiazepine (typically chlordiazepoxide, via a symptom-triggered or fixed-dose reducing regimen) for withdrawal control, alongside IV thiamine (Pabrinex) to prevent/treat Wernicke's encephalopathy, given before any glucose-containing fluids or food (as glucose administered to a thiamine-deficient patient can precipitate or worsen Wernicke's encephalopathy), with close monitoring given the severity.$x$, 4),
('dc000000-0000-0000-0000-000000000041', 'E', 'Discharge home with a reducing course of oral diazepam to be taken unsupervised', false, 'Ruled out because established delirium tremens with autonomic instability, hallucinations and disorientation is a medical emergency requiring inpatient monitored treatment, not unsupervised outpatient management.', 5),
('dc000000-0000-0000-0000-000000000042', 'A', 'Give naloxone once, and discharge immediately once he is alert and oxygen saturations have normalised', false, 'Ruled out because with concurrent long-acting opioid (methadone) use, there is a significant risk of re-sedation after naloxone wears off; immediate discharge without a period of monitored observation risks a fatal recurrence of respiratory depression.', 1),
('dc000000-0000-0000-0000-000000000042', 'B', 'Withhold naloxone due to concerns about precipitating acute opioid withdrawal, and manage with supportive oxygen therapy alone', false, 'Ruled out because severe respiratory depression with hypoxia is immediately life-threatening; naloxone should be given promptly (titrated to reverse respiratory depression while minimising precipitated withdrawal where possible) rather than withheld due to withdrawal concerns.', 2),
('dc000000-0000-0000-0000-000000000042', 'C', 'Administer flumazenil as the first-line reversal agent for this presentation', false, 'Ruled out because flumazenil is the reversal agent for benzodiazepine toxicity, not opioid toxicity; the clinical picture (pinpoint pupils, severe respiratory depression, track marks) is classic for opioid toxicity, requiring naloxone.', 3),
('dc000000-0000-0000-0000-000000000042', 'D', 'Give a single dose of naloxone and immediately discharge with a take-home naloxone kit but no period of hospital observation', false, 'Ruled out because take-home naloxone is an important harm-reduction measure for future events, but does not replace the need for a period of monitored hospital observation after this acute overdose, particularly given the re-sedation risk from concurrent long-acting opioid use.', 4),
('dc000000-0000-0000-0000-000000000042', 'E', $x$Give IV or IM naloxone to reverse respiratory depression, support ventilation as needed, and admit for a prolonged period of observation given the risk of re-sedation from naloxone's short half-life relative to long-acting opioids such as methadone$x$, true, 'Correct. This presentation (pinpoint pupils, severe respiratory depression, reduced consciousness, IV drug use history) is classic opioid toxicity requiring immediate naloxone administration and ventilatory support as needed. Given his use of methadone (a long-acting opioid) in addition to heroin, there is a significant risk of re-sedation and recurrent respiratory depression once the relatively short-acting naloxone wears off before the opioid has been fully cleared; he therefore requires a prolonged period of monitored observation, not immediate discharge after initial reversal.', 5),
('dc000000-0000-0000-0000-000000000043', 'A', 'Start high-dose methadone immediately without any ECG monitoring given the priority of retaining him in treatment', false, 'Ruled out because methadone is associated with dose-dependent QTc prolongation and torsades de pointes risk, and baseline ECG monitoring (already showing prolongation here) is an important safety step before and during methadone treatment; starting without any monitoring in a patient with a known prolonged QTc is unsafe.', 1),
('dc000000-0000-0000-0000-000000000043', 'B', 'Consider buprenorphine as an appropriate first-line option, particularly given the baseline QTc prolongation and his wish to minimise supervised consumption burden, while methadone remains an alternative with appropriate ECG monitoring if buprenorphine is unsuitable or ineffective', true, 'Correct. Both buprenorphine and methadone are effective, evidence-based options for opioid substitution therapy, and the choice is individualised. Buprenorphine (a partial opioid agonist) carries a substantially lower risk of QTc prolongation and respiratory depression compared with methadone, making it a favourable choice here given his baseline QTc prolongation; it also has a lower overdose risk profile and a more flexible dosing/supervision approach in many services, aligning with his preferences, while methadone remains a reasonable alternative if buprenorphine is not tolerated or effective, with careful ECG monitoring given his baseline prolongation.', 2),
('dc000000-0000-0000-0000-000000000043', 'C', 'Advise abrupt cessation of all opioids with no substitution therapy, relying on his motivation to stay abstinent', false, 'Ruled out because abrupt opioid cessation without substitution therapy carries a high risk of severe withdrawal, relapse and, critically, a markedly increased risk of fatal overdose due to loss of tolerance if he returns to illicit use; substitution therapy is the evidence-based harm-reduction approach.', 3),
('dc000000-0000-0000-0000-000000000043', 'D', 'Refuse to offer any opioid substitution therapy because of the baseline QTc prolongation', false, 'Ruled out because QTc prolongation does not preclude opioid substitution therapy altogether; it informs the choice of agent (favouring buprenorphine, which has minimal QTc effect) rather than being a reason to withhold this evidence-based, overdose-reducing treatment entirely.', 4),
('dc000000-0000-0000-0000-000000000043', 'E', 'Start naltrexone as first-line maintenance therapy while he is still actively using heroin daily', false, 'Ruled out because naltrexone (an opioid antagonist) can precipitate acute, severe withdrawal in a patient with current opioid dependence and is only appropriate after a period of confirmed abstinence/detoxification, not as an initial substitution therapy in someone still actively using.', 5),
('dc000000-0000-0000-0000-000000000044', 'A', 'Avoid flumazenil in this context, and instead manage with supportive care (airway protection, monitoring, treating complications) given the significant risk of precipitating seizures, particularly with her epilepsy and mixed/unknown co-ingestion', true, 'Correct. Flumazenil, a benzodiazepine antagonist, is generally avoided in benzodiazepine overdose except in very specific, carefully selected circumstances (e.g., iatrogenic over-sedation from a known, isolated benzodiazepine dose) because it can precipitate severe, treatment-resistant seizures, particularly in patients who are benzodiazepine-tolerant, have co-ingested pro-convulsant substances, or have an underlying seizure disorder (as here, with known epilepsy on carbamazepine). The priority in this mixed, intentional overdose with reduced consciousness is supportive management: airway protection, close monitoring, and treatment of complications, not reversal with flumazenil.', 1),
('dc000000-0000-0000-0000-000000000044', 'B', 'Give flumazenil immediately to reverse the reduced consciousness and avoid the need for airway management', false, 'Ruled out because flumazenil carries a significant risk of precipitating seizures in this context (known epilepsy, mixed/uncertain co-ingestion, likely benzodiazepine tolerance in someone taking diazepam), and reversing sedation does not remove the need for careful airway assessment and supportive care; this is not an appropriate use of flumazenil.', 2),
('dc000000-0000-0000-0000-000000000044', 'C', 'Give naloxone as the priority reversal agent given her reduced consciousness', false, 'Ruled out because there is no indication of opioid co-ingestion here (the history specifies diazepam and alcohol only, with no opioid features described), so naloxone is not indicated as the priority intervention; supportive management of the benzodiazepine/alcohol overdose is the correct approach.', 3),
('dc000000-0000-0000-0000-000000000044', 'D', 'Perform gastric lavage as the priority intervention given the recent ingestion', false, 'Ruled out because gastric lavage is not routinely recommended in modern overdose management due to limited evidence of benefit and risk of complications (aspiration, in a patient with reduced consciousness); airway protection and supportive care are the priority.', 4),
('dc000000-0000-0000-0000-000000000044', 'E', 'Administer activated charcoal regardless of the time since ingestion or her conscious level', false, 'Ruled out because activated charcoal carries aspiration risk in a patient with a reduced conscious level (GCS 8) and an unprotected airway, and its use is time- and context-dependent; airway protection takes priority, and charcoal should not be given without first addressing airway safety.', 5),
('dc000000-0000-0000-0000-000000000045', 'A', 'Give IV beta-blocker (e.g., metoprolol) as first-line therapy to control the tachycardia and hypertension', false, 'Ruled out because beta-blockers in cocaine toxicity can cause unopposed alpha-adrenergic stimulation (from blocking beta-mediated vasodilation while alpha-mediated vasoconstriction continues), worsening coronary vasospasm and hypertension; they are specifically avoided in the acute management of cocaine-associated chest pain/ACS.', 1),
('dc000000-0000-0000-0000-000000000045', 'B', 'Withhold all treatment for 24 hours to allow cocaine to be metabolised before any intervention', false, 'Ruled out because this presentation represents an acute coronary syndrome with ST elevation and troponin rise, a time-critical emergency requiring immediate treatment (benzodiazepines, GTN, standard ACS pathway, urgent cardiology input), not a 24-hour delay.', 2),
('dc000000-0000-0000-0000-000000000045', 'C', 'Give IV benzodiazepines and glyceryl trinitrate for symptom and blood pressure control, manage as acute coronary syndrome with standard antiplatelet/anticoagulant therapy and urgent cardiology involvement, and avoid beta-blockers', true, 'Correct. Cocaine-induced acute coronary syndrome results from coronary vasospasm and increased myocardial oxygen demand due to sympathetic stimulation. Benzodiazepines reduce central sympathetic drive and are a recommended adjunct, along with glyceryl trinitrate for vasodilation and blood pressure/symptom control; standard ACS management (antiplatelets, anticoagulation, urgent cardiology assessment for reperfusion) should proceed, but beta-blockers should specifically be avoided in the acute setting.', 3),
('dc000000-0000-0000-0000-000000000045', 'D', 'Give labetalol, as its combined alpha and beta-blocking properties make it safe in cocaine toxicity', false, 'Ruled out because although labetalol has some alpha-blocking activity, beta-blockers (including mixed agents) are generally avoided in the acute management of cocaine-associated chest pain due to residual concern about unopposed alpha-effects and lack of robust evidence of safety in this specific context; benzodiazepines and nitrates remain the preferred initial agents.', 4),
('dc000000-0000-0000-0000-000000000045', 'E', 'Perform immediate thrombolysis without first considering benzodiazepines, nitrates or standard risk assessment', false, 'Ruled out because initial management should include benzodiazepines and nitrates alongside urgent cardiology assessment; the definitive reperfusion strategy (primary PCI preferred where available, thrombolysis if not) follows standard ACS pathways and clinical assessment, not indiscriminate immediate thrombolysis bypassing initial supportive treatment and assessment.', 5),
('dc000000-0000-0000-0000-000000000046', 'A', 'Give IV dextrose first to correct the low-normal glucose, then thiamine afterwards', false, $x$Ruled out because giving glucose before thiamine in this at-risk patient can precipitate or worsen Wernicke's encephalopathy; thiamine must be given first (or at minimum concurrently), never delayed until after glucose.$x$, 1),
('dc000000-0000-0000-0000-000000000046', 'B', 'Manage conservatively with oral thiamine tablets alone given the mild presentation', false, $x$Ruled out because established or strongly suspected Wernicke's encephalopathy requires urgent, high-dose parenteral (IV) thiamine replacement, as oral absorption is unreliable and inadequate to rapidly correct severe deficiency in this emergency; oral thiamine alone risks progression to irreversible Korsakoff syndrome.$x$, 2),
('dc000000-0000-0000-0000-000000000046', 'C', 'Delay thiamine treatment until MRI brain imaging has confirmed the diagnosis', false, $x$Ruled out because Wernicke's encephalopathy is a clinical diagnosis requiring immediate empirical treatment; delaying treatment to await imaging risks irreversible neurological damage, and imaging (if used at all) should not delay urgent thiamine administration.$x$, 3),
('dc000000-0000-0000-0000-000000000046', 'D', 'Treat only the diplopia symptomatically with an eye patch and no other intervention', false, $x$Ruled out because this significantly understates the acuity of the presentation; the underlying life-threatening, treatable cause (thiamine deficiency causing Wernicke's encephalopathy) must be addressed urgently with IV thiamine, not symptomatic management of an isolated feature.$x$, 4),
('dc000000-0000-0000-0000-000000000046', 'E', $x$Give urgent high-dose IV thiamine (Pabrinex) before administering any glucose-containing fluids, to treat suspected Wernicke's encephalopathy and prevent progression to irreversible Korsakoff syndrome$x$, true, $x$Correct. The classic triad of confusion, ataxia and ophthalmoplegia (here, bilateral sixth nerve palsy) in a malnourished patient with heavy alcohol use is Wernicke's encephalopathy, a medical emergency requiring urgent treatment with high-dose IV thiamine (Pabrinex) before any glucose is given, since glucose administration in a thiamine-deficient state can precipitate or worsen Wernicke's encephalopathy. Prompt, adequate thiamine replacement is essential to prevent progression to Korsakoff syndrome, which involves largely irreversible anterograde and retrograde amnesia with confabulation.$x$, 5),
('dc000000-0000-0000-0000-000000000047', 'A', 'Manage supportively with close monitoring of vital signs, benzodiazepines for agitation if needed, IV fluids, and treatment of specific complications as they arise, recognising that a negative standard urine drug screen does not exclude novel psychoactive substance use', true, 'Correct. Synthetic cannabinoids and other novel psychoactive substances are not reliably detected by standard immunoassay urine drug screens, so a negative result does not exclude their use, particularly with a clear reported history of use and a compatible clinical picture (sympathomimetic toxidrome: tachycardia, hypertension, agitation, sweating, with variable consciousness level). Management is predominantly supportive: close cardiovascular and neurological monitoring, benzodiazepines for significant agitation, IV fluids, and treatment of specific complications (e.g., seizures, hyperthermia, arrhythmia) as they arise, since there is no specific antidote.', 1),
('dc000000-0000-0000-0000-000000000047', 'B', 'Conclude he has not taken any drug given the negative urine drug screen, and discharge immediately', false, 'Ruled out because standard urine drug screens do not reliably detect novel psychoactive substances such as synthetic cannabinoids; a negative screen in this context does not exclude the reported ingestion, and his significant clinical toxicity requires monitoring rather than dismissal and discharge.', 2),
('dc000000-0000-0000-0000-000000000047', 'C', 'Give a specific antidote for synthetic cannabinoid toxicity, as one exists for this drug class', false, 'Ruled out because there is no specific antidote for synthetic cannabinoid (or most novel psychoactive substance) toxicity; management is supportive, addressing the clinical features and complications as they arise.', 3),
('dc000000-0000-0000-0000-000000000047', 'D', 'Give naloxone as the priority intervention given his fluctuating consciousness level', false, 'Ruled out because there is no history or clinical feature (pinpoint pupils, primary respiratory depression) suggesting opioid toxicity here; the clinical picture is a sympathomimetic toxidrome consistent with synthetic cannabinoid use, and naloxone would not be expected to have any specific benefit.', 4),
('dc000000-0000-0000-0000-000000000047', 'E', 'Administer a beta-blocker as first-line treatment for the tachycardia and hypertension', false, 'Ruled out because, similar to other sympathomimetic toxidromes, beta-blockade risks unopposed alpha-adrenergic effects worsening hypertension and vasospasm; supportive management with benzodiazepines for agitation/sympathetic overactivity is preferred over beta-blockers.', 5),
('dc000000-0000-0000-0000-000000000048', 'A', 'Manage as a mild, self-limiting withdrawal syndrome with oral benzodiazepines only on a general ward with routine observation', false, 'Ruled out because GHB/GBL withdrawal, particularly with a history of previous severe/rapidly escalating episodes, can progress extremely quickly to a severe, life-threatening state; a general ward with routine observations and standard oral dosing is not sufficiently intensive given this risk.', 1),
('dc000000-0000-0000-0000-000000000048', 'B', 'Withhold benzodiazepines due to concerns about dependence, and manage purely with reassurance', false, 'Ruled out because benzodiazepines are the mainstay of treatment for GHB/GBL withdrawal, and withholding them in this context risks rapid, severe, potentially life-threatening deterioration; short-term dependence concerns are not relevant to the immediate management of an acute, dangerous withdrawal syndrome.', 2),
('dc000000-0000-0000-0000-000000000048', 'C', 'Treat as evolving severe GHB/GBL withdrawal, which can progress extremely rapidly to a severe, life-threatening state; initiate high-dose benzodiazepine treatment early and arrange for a monitored/high-dependency bed given the risk of rapid deterioration', true, 'Correct. GHB/GBL withdrawal is distinctive among substance withdrawal syndromes for how rapidly it can progress, sometimes within hours, from mild symptoms to severe agitation, delirium, autonomic instability and even life-threatening complications (seizures, cardiovascular collapse), often requiring much higher benzodiazepine doses than typical alcohol withdrawal regimens. Given the history of previous severe, rapidly escalating episodes requiring intensive care, early, assertive benzodiazepine treatment and a monitored/high-dependency level of care are appropriate to prevent rapid deterioration.', 3),
('dc000000-0000-0000-0000-000000000048', 'D', 'Start naltrexone to manage the withdrawal symptoms', false, 'Ruled out because naltrexone is an opioid antagonist used in relapse prevention for opioid or alcohol use disorder, not a treatment for GHB/GBL withdrawal, and has no role in the acute management of this presentation.', 4),
('dc000000-0000-0000-0000-000000000048', 'E', 'Discharge home now that she appears alert, with community follow-up arranged for the following week', false, 'Ruled out because the described pattern (rapid progression from lucidity to severe agitation and confusion within ninety minutes, prior severe episodes) indicates high risk of imminent, severe deterioration; discharge at this point is unsafe, and admission for monitored treatment is required.', 5),
('dc000000-0000-0000-0000-000000000049', 'A', 'Start disulfiram as first-line, since its aversive reaction is the most effective way to prevent relapse', false, $x$Ruled out because disulfiram works by causing a severe, potentially dangerous reaction (flushing, tachycardia, hypotension, vomiting) if alcohol is consumed, which directly conflicts with this patient's expressed wish to avoid a medication with a severe reaction risk if he were to lapse; it also requires careful patient selection and is not automatically first-line for everyone.$x$, 1),
('dc000000-0000-0000-0000-000000000049', 'B', 'Start naltrexone at standard dose without further consideration, as it is always the first choice regardless of liver function', false, $x$Ruled out because naltrexone carries a risk of hepatotoxicity and requires caution and monitoring in patients with liver impairment; while it can sometimes still be used with monitoring, it is not clearly the most appropriate 'without further consideration' choice given his hepatic impairment and stated preference, compared with acamprosate's more favourable profile here.$x$, 2),
('dc000000-0000-0000-0000-000000000049', 'C', 'Recommend no pharmacotherapy at all, as psychological support alone is sufficient after successful detoxification', false, 'Ruled out because relapse-prevention pharmacotherapy, combined with psychosocial support, improves outcomes after alcohol detoxification and should be actively offered and discussed as an option, not dismissed given his liver disease is only mild/compensated.', 3),
('dc000000-0000-0000-0000-000000000049', 'D', 'Consider acamprosate as a suitable first-line option given it is renally excreted (appropriate given normal renal function) and does not carry the same hepatotoxicity concerns as naltrexone or the dangerous reaction-on-drinking profile of disulfiram', true, $x$Correct. Acamprosate acts on glutamatergic/GABAergic systems to reduce craving, is renally excreted (making it a reasonable choice with normal renal function, though requiring caution/dose adjustment in renal impairment rather than hepatic impairment), and does not carry a significant hepatotoxicity risk or the severe, dangerous reaction with alcohol characteristic of disulfiram, matching this patient's clinical profile (mild liver impairment, wish to avoid a medication with a dangerous reaction if he lapses).$x$, 4),
('dc000000-0000-0000-0000-000000000049', 'E', 'Start high-dose benzodiazepine as long-term relapse-prevention therapy', false, 'Ruled out because benzodiazepines are not an appropriate long-term relapse-prevention treatment for alcohol use disorder; they carry their own dependence risk and are not indicated for this purpose once withdrawal has been safely managed.', 5),
('dc000000-0000-0000-0000-000000000050', 'A', 'Diagnose primary schizophrenia and commit to long-term antipsychotic maintenance therapy immediately', false, 'Ruled out because this presentation, with a clear temporal relationship to heavy stimulant use and sleep deprivation and preserved orientation, is most consistent with substance-induced psychosis, which often resolves with abstinence and supportive/short-term treatment; committing immediately to a primary schizophrenia diagnosis and long-term antipsychotic maintenance is premature without further observation over time.', 1),
('dc000000-0000-0000-0000-000000000050', 'B', 'Manage in a calm, low-stimulus environment with benzodiazepines for agitation and a short course of antipsychotic medication if psychotic symptoms persist or are severe, alongside monitoring of cardiovascular parameters', true, 'Correct. This presentation (persecutory delusions, tactile hallucinations/skin picking, agitation, tachycardia and hypertension, in the context of heavy recent stimulant use with sleep deprivation, but with preserved orientation) is classic stimulant (amphetamine/methamphetamine)-induced psychosis. Management involves a calm environment to reduce sensory overstimulation, benzodiazepines for agitation and to help with sleep, and antipsychotic medication if psychotic symptoms are severe or persistent, alongside monitoring for cardiovascular complications given the sympathomimetic toxicity (tachycardia, hypertension).', 2),
('dc000000-0000-0000-0000-000000000050', 'C', 'Give IV beta-blocker as first-line treatment for the tachycardia and hypertension', false, 'Ruled out because, as with other sympathomimetic toxidromes (cocaine, synthetic cannabinoids), beta-blockade risks unopposed alpha-adrenergic effects worsening vasoconstriction and hypertension; benzodiazepines are preferred for controlling the sympathetic overactivity and agitation.', 3),
('dc000000-0000-0000-0000-000000000050', 'D', $x$Withhold all treatment and allow the psychosis to resolve without any intervention, as this is 'just a drug effect'$x$, false, 'Ruled out because although stimulant-induced psychosis often resolves with abstinence, active management (calm environment, benzodiazepines, antipsychotic if needed) is appropriate to manage distress, agitation and risk in the acute phase, rather than withholding all treatment.', 4),
('dc000000-0000-0000-0000-000000000050', 'E', 'Administer naloxone as the first-line intervention given his agitation', false, 'Ruled out because there is no history or clinical feature suggesting opioid toxicity (no reduced consciousness, no pinpoint pupils, no respiratory depression); the clinical picture is a stimulant-related sympathomimetic and psychotic presentation, for which naloxone has no role.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('dc000000-0000-0000-0000-000000000001', 'In panic disorder with an inadequate response to an adequate SSRI trial (correct dose and duration, combined with CBT), switching to an SNRI such as venlafaxine is the recommended next pharmacological step.', 1),
('dc000000-0000-0000-0000-000000000001', 'Benzodiazepines should be avoided as long-term maintenance therapy in anxiety disorders because of dependence, tolerance and withdrawal risks; their role is limited to short-term crisis management.', 2),
('dc000000-0000-0000-0000-000000000001', 'Psychological therapy (CBT) should generally be continued alongside a medication switch rather than withdrawn, as combined treatment produces better outcomes than either modality alone.', 3),
('dc000000-0000-0000-0000-000000000002', 'SSRIs can cause SIADH and clinically significant hyponatraemia, particularly in the first few weeks of treatment and more commonly in older or female patients; the causative drug should be identified and stopped.', 1),
('dc000000-0000-0000-0000-000000000002', 'SIADH is characterised by hyponatraemia with inappropriately concentrated urine relative to plasma osmolality, in the absence of renal, adrenal, or thyroid dysfunction, and with the patient euvolaemic.', 2),
('dc000000-0000-0000-0000-000000000002', 'Correction of hyponatraemia should be cautious and guided by severity/symptoms to avoid osmotic demyelination syndrome from overly rapid sodium correction; hypertonic saline is reserved for severe or seizing patients.', 3),
('dc000000-0000-0000-0000-000000000003', 'Illness anxiety disorder (health anxiety) is characterised by persistent, disproportionate preoccupation with having or acquiring a serious illness, high health-related anxiety, and excessive health-related behaviours (checking) or maladaptive avoidance, despite appropriate medical reassurance.', 1),
('dc000000-0000-0000-0000-000000000003', 'CBT targeted specifically at health anxiety is the evidence-based first-line treatment; repeated investigation reinforces rather than resolves the anxiety cycle.', 2),
('dc000000-0000-0000-0000-000000000003', 'A single coordinated care plan, ideally through one gatekeeping clinician, reduces fragmented care and unnecessary repeat investigation in patients with high healthcare utilisation driven by health anxiety.', 3),
('dc000000-0000-0000-0000-000000000004', 'Functional (dissociative, non-epileptic) seizures are diagnosed on positive clinical features (e.g., forced eye closure, long duration, fluctuating course, asynchronous limb movements) plus video-EEG showing no epileptiform correlate during typical events — it is a rule-in, not purely a diagnosis of exclusion.', 1),
('dc000000-0000-0000-0000-000000000004', 'Clear, sensitive communication of the FND diagnosis, using objective evidence such as video-EEG, and stopping unnecessary antiepileptic drugs, are key early management steps.', 2),
('dc000000-0000-0000-0000-000000000004', 'Specialist psychological therapy and FND-focused rehabilitation (e.g., specialist physiotherapy for functional motor symptoms) have the strongest evidence base for improving outcomes in functional neurological disorder.', 3),
('dc000000-0000-0000-0000-000000000005', 'In somatic symptom disorder, repeated investigation provides only short-lived reassurance and reinforces anxiety and health-seeking behaviour; unnecessary repeat testing should be avoided unless new objective clinical findings arise.', 1),
('dc000000-0000-0000-0000-000000000005', 'Continuity of care through a single named clinician reduces fragmented, duplicative investigation and improves therapeutic engagement in patients with high healthcare utilisation from somatic symptom disorder.', 2),
('dc000000-0000-0000-0000-000000000005', 'Management should shift focus from symptom elimination to improving function and quality of life, typically through CBT-based or multidisciplinary pain-management programmes.', 3),
('dc000000-0000-0000-0000-000000000006', 'Trauma-focused CBT and EMDR are first-line treatments for PTSD in adults, generally preferred over pharmacotherapy as initial management.', 1),
('dc000000-0000-0000-0000-000000000006', 'Benzodiazepines are not recommended in PTSD: they do not treat core symptoms, carry dependence risk, and may reduce the efficacy of trauma-focused psychological therapy.', 2),
('dc000000-0000-0000-0000-000000000006', 'Routine single-session debriefing immediately post-trauma is not evidence-based for PTSD prevention and is not recommended.', 3),
('dc000000-0000-0000-0000-000000000007', 'For OCD not responding to an adequate SSRI trial, options include switching to an alternative SSRI or trying clomipramine, alongside continued exposure and response prevention therapy.', 1),
('dc000000-0000-0000-0000-000000000007', 'Clomipramine is an effective but second-line option in OCD due to its tricyclic side-effect and cardiotoxicity profile, requiring baseline and interval ECG monitoring.', 2),
('dc000000-0000-0000-0000-000000000007', 'Antipsychotic augmentation of an SSRI/clomipramine is reserved for genuinely treatment-resistant OCD after adequate serotonergic drug trials, not as first-line or monotherapy.', 3),
('dc000000-0000-0000-0000-000000000008', 'Body dysmorphic disorder is treated with SSRIs (often OCD-range doses) and CBT specifically adapted for BDD; cosmetic or surgical intervention should be actively discouraged as it rarely resolves symptoms.', 1),
('dc000000-0000-0000-0000-000000000008', 'Reassurance about appearance is not durably effective in BDD, distinguishing it from normal appearance concerns and guiding clinicians away from repeated reassurance as a management strategy.', 2),
('dc000000-0000-0000-0000-000000000008', 'BDD shares treatment principles with OCD (SSRI plus CBT) reflecting its classification within the obsessive-compulsive spectrum of disorders.', 3),
('dc000000-0000-0000-0000-000000000009', 'Serotonin syndrome results from combining serotonergic agents (e.g., SSRI plus tramadol, or an SSRI/SNRI plus an MAOI or linezolid) and presents with the triad of neuromuscular hyperactivity (clonus, hyperreflexia, tremor, myoclonus, typically more pronounced in the lower limbs), autonomic instability (fever, tachycardia, diaphoresis) and altered mental state.', 1),
('dc000000-0000-0000-0000-000000000009', 'Management is immediate withdrawal of all serotonergic drugs, supportive care (fluids, cooling, benzodiazepines), with cyproheptadine (a serotonin antagonist) for moderate-to-severe or refractory cases.', 2),
('dc000000-0000-0000-0000-000000000009', 'Serotonin syndrome should be distinguished from neuroleptic malignant syndrome: clonus/hyperreflexia and rapid onset (within hours) favour serotonin syndrome, whereas lead-pipe rigidity and slower onset over days favour NMS, and dantrolene is specific to NMS/malignant hyperthermia, not serotonin syndrome.', 3),
('dc000000-0000-0000-0000-000000000010', 'After prolonged, high-dose benzodiazepine use, discontinuation should be gradual (dose tapering, often over weeks to months) to reduce the risk of withdrawal seizures, severe rebound anxiety and autonomic instability.', 1),
('dc000000-0000-0000-0000-000000000010', 'Long-acting benzodiazepines such as diazepam are generally preferred as the vehicle for tapering, as they produce a smoother, more gradual withdrawal than short-acting agents like lorazepam.', 2),
('dc000000-0000-0000-0000-000000000010', 'Long-term benzodiazepine use in older adults carries additional risks including falls, cognitive impairment and dependence, supporting a planned, supported discontinuation when clinically appropriate.', 3),
('dc000000-0000-0000-0000-000000000011', 'Capacity assessment under the Mental Capacity Act 2005 is decision-specific and time-specific: a diagnosis (e.g., dementia) alone never determines incapacity — the functional test must be applied to the particular decision.', 1),
('dc000000-0000-0000-0000-000000000011', 'The functional test requires the person to understand, retain, use/weigh the relevant information, and communicate their decision; inability in any one of these elements means capacity is lacking for that decision.', 2),
('dc000000-0000-0000-0000-000000000011', $x$In England and Wales, next of kin do not have automatic legal authority to consent on behalf of an adult who lacks capacity; if incapacity is confirmed, decisions are made in the patient's best interests by the treating team, informed by consultation with family.$x$, 3),
('dc000000-0000-0000-0000-000000000012', 'When a patient lacks capacity and has no valid advance decision or lasting power of attorney with relevant authority, treatment decisions are made in their best interests, with the treating clinician(s) holding final responsibility.', 1),
('dc000000-0000-0000-0000-000000000012', $x$The best interests checklist requires consultation with those close to the patient about the patient's previously expressed wishes, feelings, values and beliefs, but family members do not have the power to make or veto the decision themselves.$x$, 2),
('dc000000-0000-0000-0000-000000000012', 'An Independent Mental Capacity Advocate (IMCA) is appointed specifically when a patient lacking capacity has no family or friends appropriate to consult, not as a substitute for family consultation when family disagree.', 3),
('dc000000-0000-0000-0000-000000000013', 'Incapacity arising from an acute physical illness (e.g., delirium from a UTI) is managed under the Mental Capacity Act using best interests decision-making and proportionate restraint/restriction, not primarily via Mental Health Act sectioning.', 1),
('dc000000-0000-0000-0000-000000000013', $x$Section 5(2) MHA (the doctor's holding power) is designed for patients already admitted for treatment of mental disorder who attempt to leave; it is not the default tool for physically unwell, delirious patients on general medical wards.$x$, 2),
('dc000000-0000-0000-0000-000000000013', $x$Any restriction of a patient's liberty must be justified under a recognised legal framework and be proportionate to the risk of harm; prolonged or intense restriction may itself require separate deprivation-of-liberty authorisation.$x$, 3),
('dc000000-0000-0000-0000-000000000014', 'Section 3 MHA is used for detention for treatment (up to 6 months) when the diagnosis and treatment plan are established, appropriate treatment is available, and the patient is unwilling to be admitted informally — distinguishing it from Section 2, which is for assessment.', 1),
('dc000000-0000-0000-0000-000000000014', 'Where inpatient psychiatric treatment is needed for a mental disorder and the patient objects, the Mental Health Act (not the Mental Capacity Act) is generally the appropriate legal framework, since the MCA does not authorise this degree of restrictive treatment against objection.', 2),
('dc000000-0000-0000-0000-000000000014', $x$Family members have no legal authority in England and Wales to consent to psychiatric admission or treatment on a patient's behalf; formal statutory processes (MHA assessment) must be followed.$x$, 3),
('dc000000-0000-0000-0000-000000000015', $x$A deprivation of liberty is identified using the 'acid test': the person is under continuous supervision and control and is not free to leave; where this applies to a person lacking capacity, statutory authorisation (DoLS, transitioning to LPS) is required in addition to ordinary best interests treatment decisions.$x$, 1),
('dc000000-0000-0000-0000-000000000015', $x$Restriction arising from a physical health admission in a person with dementia is authorised through the Mental Capacity Act's deprivation of liberty framework, not through Mental Health Act detention, when the underlying need is physical healthcare rather than psychiatric treatment.$x$, 2),
('dc000000-0000-0000-0000-000000000015', 'Lack of capacity does not remove the legal requirement to authorise a deprivation of liberty; restriction must always be lawfully justified, proportionate, and time-limited with review.', 3),
('dc000000-0000-0000-0000-000000000016', 'A valid and applicable advance decision to refuse treatment (ADRT) under the Mental Capacity Act is legally binding, even where it refuses life-sustaining treatment, provided it was made with capacity, is specific to the circumstances that have arisen, and has not been withdrawn.', 1),
('dc000000-0000-0000-0000-000000000016', 'Advance decisions are specifically designed to take effect once the person has lost capacity (e.g., unconsciousness); this is precisely the situation in which they are intended to apply, not a reason to disregard them.', 2),
('dc000000-0000-0000-0000-000000000016', 'Next of kin have no legal authority in England and Wales to consent to or refuse treatment on behalf of an adult, and cannot override a valid advance decision made by the patient themselves.', 3),
('dc000000-0000-0000-0000-000000000017', 'Section 62 MHA allows urgent treatment to bypass the normal Part 4 consent-to-treatment safeguards (e.g., SOAD certification) when treatment is immediately necessary to save life, prevent serious deterioration, or alleviate serious suffering.', 1),
('dc000000-0000-0000-0000-000000000017', $x$Detention under the Mental Health Act governs treatment for mental disorder; treatment of unrelated physical health conditions in a patient lacking capacity is provided under the Mental Capacity Act's best interests and emergency treatment principles, running in parallel with ongoing psychiatric detention.$x$, 2),
('dc000000-0000-0000-0000-000000000017', 'In a genuine medical/surgical emergency, treatment should not be delayed to await procedural safeguards (SOAD certificates, formal capacity paperwork) when doing so would risk serious harm; emergency provisions exist precisely for this situation.', 3),
('dc000000-0000-0000-0000-000000000018', $x$Delirium characteristically causes fluctuating capacity; capacity assessments should ideally be timed to lucid intervals for non-urgent decisions, with clear documentation, and reassessed if the patient's condition changes.$x$, 1),
('dc000000-0000-0000-0000-000000000018', 'Capacity is decision-specific and time-specific — a single episode of confusion does not permanently establish incapacity, particularly when an underlying reversible cause (such as an infection driving delirium) is being actively treated.', 2),
('dc000000-0000-0000-0000-000000000018', 'Family members do not have automatic legal authority to make treatment decisions for an adult with fluctuating capacity; formal, individualised capacity assessment of the patient remains central to the process.', 3),
('dc000000-0000-0000-0000-000000000019', 'Nasogastric or artificial feeding for severe anorexia nervosa can be provided as treatment for mental disorder under the Mental Health Act, because the physical state and the refusal of treatment are understood as direct manifestations of the underlying psychiatric illness.', 1),
('dc000000-0000-0000-0000-000000000019', 'A refusal driven by the distorted perception of risk characteristic of an eating disorder is not equivalent to a free, capacitous refusal of treatment; specific assessment of whether the illness itself is impairing the ability to weigh information is required.', 2),
('dc000000-0000-0000-0000-000000000019', 'The Mental Health Act (with appropriate age-specific safeguards) can and does apply to minors where urgent, life-threatening psychiatric-driven risk requires compulsory treatment; treatment cannot be deferred to adulthood in an emergency.', 3),
('dc000000-0000-0000-0000-000000000020', 'A detained patient who fails to return from, or absconds during, Section 17 leave is absent without leave (AWOL); the underlying detention continues, and staff or police may take the patient into custody and return them to hospital, subject to statutory time limits.', 1),
('dc000000-0000-0000-0000-000000000020', 'Responsibility for an AWOL detained patient remains with the treating team/hospital, working alongside police as needed, rather than becoming solely a police matter.', 2),
('dc000000-0000-0000-0000-000000000020', 'Granting Section 17 leave is a clinical decision about treatment setting and does not itself indicate the patient no longer meets criteria for detention; absconding does not automatically discharge the section.', 3),
('dc000000-0000-0000-0000-000000000021', 'NSAIDs, thiazide diuretics, ACE inhibitors/ARBs and dehydration (e.g., from gastroenteritis) are classic precipitants of lithium toxicity by reducing renal lithium clearance or increasing reabsorption.', 1),
('dc000000-0000-0000-0000-000000000021', 'Severe lithium toxicity (very high levels, significant neurotoxicity such as confusion, ataxia, coarse tremor, seizures, or renal impairment) requires immediate drug cessation, IV fluid resuscitation, and consideration of haemodialysis, since lithium is small, water-soluble and dialysable.', 2),
('dc000000-0000-0000-0000-000000000021', 'Chronic lithium toxicity (as opposed to acute overdose) can cause severe neurotoxicity at levels that might be tolerated acutely, because tissue (especially CNS) lithium concentrations have had time to equilibrate — clinical features guide urgency of treatment as much as the numerical level alone.', 3),
('dc000000-0000-0000-0000-000000000022', 'Treatment-resistant depression (inadequate response to at least two adequate antidepressant trials) is managed with evidence-based augmentation strategies — lithium or an atypical antipsychotic (e.g., aripiprazole, quetiapine) added to the existing antidepressant — rather than repeated simple switching within the same class.', 1),
('dc000000-0000-0000-0000-000000000022', 'Switching from an SSRI/SNRI to an MAOI requires an adequate washout period to avoid serotonin syndrome; this is an important safety principle in refractory depression management.', 2),
('dc000000-0000-0000-0000-000000000022', 'ECT is reserved for more severe or urgent presentations (e.g., psychotic depression, catatonia, high suicide risk, or failure of pharmacological augmentation strategies), not as an automatic step after only two failed antidepressant trials.', 3),
('dc000000-0000-0000-0000-000000000023', 'Catatonia is characterised by features such as mutism, negativism, waxy flexibility, posturing and stupor, and is supported diagnostically by a positive (even if temporary) response to a benzodiazepine (lorazepam) challenge.', 1),
('dc000000-0000-0000-0000-000000000023', 'First-line treatment for catatonia is a benzodiazepine (typically lorazepam); ECT is highly effective and is used when benzodiazepine response is inadequate, slow relative to physical risk, or in severe/malignant catatonia.', 2),
('dc000000-0000-0000-0000-000000000023', 'Antipsychotics, particularly high-potency first-generation agents, should generally be avoided in catatonia as they can worsen the condition and risk precipitating neuroleptic malignant syndrome.', 3),
('dc000000-0000-0000-0000-000000000024', 'Acute mania is managed with an antipsychotic (faster onset) as monotherapy or combined with a mood stabiliser such as lithium or valproate; antidepressants are avoided as they may worsen or precipitate mania.', 1),
('dc000000-0000-0000-0000-000000000024', 'In a patient with a previously effective mood stabiliser who has recently stopped it, restarting that agent alongside an antipsychotic addresses both rapid symptom control and longer-term relapse prevention.', 2),
('dc000000-0000-0000-0000-000000000024', 'Non-adherence to maintenance mood stabiliser therapy is a common and important precipitant of acute manic relapse in bipolar disorder, and should be explored and addressed as part of ongoing management.', 3),
('dc000000-0000-0000-0000-000000000025', 'Postpartum (puerperal) psychosis is a psychiatric emergency typically presenting within the first two weeks after birth with rapid-onset, fluctuating mood and psychotic symptoms, agitation and disorganisation, carrying risk to both mother and infant.', 1),
('dc000000-0000-0000-0000-000000000025', 'Specialist mother and baby units allow admission and treatment of the mother while supporting supervised mother-infant contact and bonding where safe, rather than automatic separation.', 2),
('dc000000-0000-0000-0000-000000000025', 'Risk assessment specifically addressing the safety of the infant (and mother) is a critical, ongoing part of managing postpartum psychosis given the potential for delusional beliefs to directly involve the baby.', 3),
('dc000000-0000-0000-0000-000000000026', $x$Antidepressant discontinuation syndrome typically occurs within days of abrupt cessation (or significant dose reduction) and is more common with shorter half-life agents such as paroxetine and venlafaxine; symptoms include dizziness, 'electric shock' sensations, nausea, irritability and sleep disturbance.$x$, 1),
('dc000000-0000-0000-0000-000000000026', 'Management is to restart the antidepressant at the previous effective dose to relieve symptoms, then taper gradually, rather than abrupt cessation or unnecessary dose escalation.', 2),
('dc000000-0000-0000-0000-000000000026', 'Discontinuation syndrome should be distinguished from depressive relapse by its rapid onset after stopping medication and its distinct symptom profile, in contrast to the more gradual reemergence of core depressive symptoms in true relapse.', 3),
('dc000000-0000-0000-0000-000000000027', 'Sodium valproate is associated with a high risk of major congenital malformations (including neural tube defects) and long-term neurodevelopmental impairment; it is generally avoided in women of childbearing potential unless strict criteria are met and is not continued in pregnancy where alternatives exist.', 1),
('dc000000-0000-0000-0000-000000000027', 'Abrupt discontinuation of an effective mood stabiliser in pregnancy risks rapid relapse, which itself carries maternal and pregnancy risks; medication changes in pregnancy should be planned and gradual with specialist perinatal psychiatry involvement.', 2),
('dc000000-0000-0000-0000-000000000027', 'Decisions about continuing a pregnancy are for the patient with full, balanced specialist information, not a default clinical recommendation based on medication exposure alone.', 3),
('dc000000-0000-0000-0000-000000000028', 'Rapid-cycling bipolar disorder is defined as four or more distinct mood episodes within a twelve-month period, and is a recognised indication to avoid antidepressant monotherapy.', 1),
('dc000000-0000-0000-0000-000000000028', 'Antidepressant monotherapy in bipolar disorder can worsen cycling frequency or precipitate a switch into hypomania/mania; an appropriate mood stabiliser should be the primary long-term treatment.', 2),
('dc000000-0000-0000-0000-000000000028', 'Choice of mood stabiliser should take into account patient-specific factors (e.g., avoiding valproate in women of childbearing potential where possible) alongside efficacy for rapid cycling.', 3),
('dc000000-0000-0000-0000-000000000029', 'Mixed affective episodes (simultaneous depressive and manic/hypomanic features) carry a particularly high risk of suicide, combining low mood and hopelessness with the energy, impulsivity and agitation of mania, and require urgent assessment.', 1),
('dc000000-0000-0000-0000-000000000029', 'Antidepressant monotherapy is inappropriate and potentially dangerous in mixed states and in bipolar disorder generally, as it can worsen the manic/agitated component; treatment centres on antipsychotics and/or mood stabilisers.', 2),
('dc000000-0000-0000-0000-000000000029', 'Any bipolar presentation with new or escalating suicidal ideation, particularly with mixed or agitated features, warrants urgent same-day psychiatric assessment rather than routine follow-up.', 3),
('dc000000-0000-0000-0000-000000000030', 'Lithium has the strongest evidence of any psychotropic medication for reducing suicide risk and suicide-related mortality in patients with recurrent mood disorders, an effect that appears at least partly independent of its general mood-stabilising properties.', 1),
('dc000000-0000-0000-0000-000000000030', 'A pattern of repeated relapse each time effective medication is withdrawn is an important indicator for long-term maintenance treatment, including consideration of augmentation strategies such as lithium, rather than repeated discontinuation attempts.', 2),
('dc000000-0000-0000-0000-000000000030', 'Long-term lithium therapy requires ongoing monitoring of serum levels, renal function and thyroid function given its narrow therapeutic index and recognised long-term adverse effects.', 3),
('dc000000-0000-0000-0000-000000000031', 'Clozapine requires mandatory, regular haematological monitoring (full blood count) due to the risk of potentially fatal agranulocytosis; monitoring frequency and thresholds for stopping the drug are defined by amber/red categories based on absolute neutrophil count.', 1),
('dc000000-0000-0000-0000-000000000031', 'Agranulocytosis on clozapine can develop and progress without initial symptoms; action must be based on the blood count result itself, not on whether the patient feels unwell.', 2),
('dc000000-0000-0000-0000-000000000031', 'Once significant clozapine-induced neutropenia/agranulocytosis has occurred, clozapine is usually permanently discontinued (rechallenge is high-risk and requires specialist haematology/psychiatry joint decision-making), and an alternative antipsychotic strategy must be planned.', 3),
('dc000000-0000-0000-0000-000000000032', 'Neuroleptic malignant syndrome presents with fever, generalised lead-pipe muscle rigidity, autonomic instability and altered consciousness, with markedly elevated creatine kinase reflecting muscle breakdown; it typically develops over days, in contrast to the more rapid (hours) onset of serotonin syndrome.', 1),
('dc000000-0000-0000-0000-000000000032', 'Management of NMS requires immediate cessation of the antipsychotic, aggressive supportive care (fluids, cooling, monitoring for rhabdomyolysis-related renal injury), and specific treatment (dantrolene, bromocriptine) in severe cases, usually in a critical care setting.', 2),
('dc000000-0000-0000-0000-000000000032', 'Further antipsychotic administration should be avoided during suspected or confirmed NMS, as this can worsen the syndrome; careful, specialist-guided reintroduction of a different antipsychotic (if needed) only occurs after full resolution.', 3),
('dc000000-0000-0000-0000-000000000033', 'Clozapine-induced myocarditis typically occurs within the first six to eight weeks of treatment (most often within the first month) and presents with tachycardia, chest pain, breathlessness, elevated troponin and CRP, sometimes with ECG changes.', 1),
('dc000000-0000-0000-0000-000000000033', 'Suspected clozapine-induced myocarditis requires immediate drug cessation and urgent cardiology assessment (including echocardiography) given the risk of progression to severe cardiomyopathy if unrecognised and the drug continued.', 2),
('dc000000-0000-0000-0000-000000000033', 'Baseline and interval monitoring of inflammatory markers, troponin and vital signs during clozapine initiation is used to detect myocarditis early, reflecting the importance of a high index of suspicion during the titration period.', 3),
('dc000000-0000-0000-0000-000000000034', 'IV haloperidol carries a significant risk of QTc prolongation and torsades de pointes, and should be avoided or used with extreme caution and cardiac monitoring when the baseline QTc is already prolonged.', 1),
('dc000000-0000-0000-0000-000000000034', 'Electrolyte abnormalities such as hypokalaemia and hypomagnesaemia (common after alcohol withdrawal) can further prolong the QTc and should be identified and corrected before or alongside using QTc-prolonging antipsychotics.', 2),
('dc000000-0000-0000-0000-000000000034', 'Where antipsychotic treatment is still required in a patient with baseline QTc prolongation, the lowest effective dose of an alternative agent with continuous cardiac monitoring, ideally with specialist input, is the safer approach.', 3),
('dc000000-0000-0000-0000-000000000035', 'Early intervention in psychosis (EIP) services provide prompt, coordinated pharmacological and psychosocial management of first-episode psychosis and are associated with improved long-term outcomes; longer duration of untreated psychosis is a recognised poor prognostic factor.', 1),
('dc000000-0000-0000-0000-000000000035', 'Antipsychotic choice in first-episode psychosis, particularly in younger patients, should carefully weigh individual side-effect risk profiles (metabolic, extrapyramidal, prolactin-related) given the potential for a long treatment course ahead.', 2),
('dc000000-0000-0000-0000-000000000035', 'Compulsory detention under the Mental Health Act is not automatic for first-episode psychosis; many patients can be engaged and treated voluntarily through specialist community-based early intervention services.', 3),
('dc000000-0000-0000-0000-000000000036', 'Treatment-resistant schizophrenia is defined as inadequate response to at least two different antipsychotics, each given at an adequate dose for an adequate duration (typically at least 6-8 weeks) with confirmed adherence.', 1),
('dc000000-0000-0000-0000-000000000036', 'Clozapine is the recommended treatment for treatment-resistant schizophrenia, with superior efficacy compared with switching between other standard antipsychotics or antipsychotic polypharmacy.', 2),
('dc000000-0000-0000-0000-000000000036', 'Clozapine initiation should not be unnecessarily delayed once treatment-resistance criteria are genuinely met, given its distinct efficacy advantage, though it requires establishing mandatory haematological monitoring.', 3),
('dc000000-0000-0000-0000-000000000037', 'Risperidone (and amisulpride) are particularly strongly associated with dose-dependent hyperprolactinaemia due to potent pituitary dopamine D2 receptor blockade, causing amenorrhoea, galactorrhoea, sexual dysfunction and, long-term, reduced bone mineral density.', 1),
('dc000000-0000-0000-0000-000000000037', 'Aripiprazole is relatively prolactin-sparing (as a partial dopamine agonist) and can be used either as a direct switch or as an adjunct to reduce prolactin levels caused by another antipsychotic.', 2),
('dc000000-0000-0000-0000-000000000037', 'Markedly elevated prolactin should prompt exclusion of a prolactinoma (e.g., pituitary imaging) particularly with very high levels or other pituitary symptoms, but a clear temporal relationship with a known prolactin-raising antipsychotic and normal imaging supports a drug-induced cause.', 3),
('dc000000-0000-0000-0000-000000000038', 'Acute dystonic reactions present with sudden, painful, sustained muscle contractions (e.g., torticollis, oculogyric crisis) typically within hours of starting or increasing the dose of a high-potency antipsychotic, and are more common in young men.', 1),
('dc000000-0000-0000-0000-000000000038', 'First-line treatment for an acute dystonic reaction is an anticholinergic agent such as procyclidine, given IM or IV for rapid relief.', 2),
('dc000000-0000-0000-0000-000000000038', 'Acute dystonia should be distinguished from neuroleptic malignant syndrome (which involves fever, generalised rigidity and autonomic instability developing over days, treated very differently) despite both being extrapyramidal/antipsychotic-related complications.', 3),
('dc000000-0000-0000-0000-000000000039', $x$Dementia with Lewy bodies (and Parkinson's disease dementia) carries a well-recognised risk of severe, potentially fatal neuroleptic sensitivity reactions to antipsychotics, particularly typical/high-potency agents such as haloperidol.$x$, 1),
('dc000000-0000-0000-0000-000000000039', 'Agitation and hallucinations in dementia should first prompt a search for and treatment of reversible precipitants (infection, pain, medication effects, environmental factors) and use of non-pharmacological strategies before considering antipsychotic medication.', 2),
('dc000000-0000-0000-0000-000000000039', 'If an antipsychotic is genuinely unavoidable in DLB, a low-dose atypical agent with lower antidopaminergic/extrapyramidal liability (such as quetiapine) is used cautiously with specialist input, not a typical antipsychotic like haloperidol.', 3),
('dc000000-0000-0000-0000-000000000040', 'Delirium is characterised by acute onset, fluctuating course (often worse at night), inattention and disorientation, typically precipitated by an identifiable acute physical illness or insult (infection, hypoxia, surgery, medication) — distinguishing it from primary psychotic illness, which usually lacks this acute, fluctuating, medically-precipitated pattern.', 1),
('dc000000-0000-0000-0000-000000000040', 'Management of delirium prioritises identifying and treating underlying reversible causes and using non-pharmacological reorientation strategies before considering pharmacological treatment.', 2),
('dc000000-0000-0000-0000-000000000040', 'Antipsychotic medication in delirium is reserved for severe agitation or distress posing risk to the patient or others, used cautiously at the lowest effective dose for the shortest duration given increased sensitivity to side effects in older patients.', 3),
('dc000000-0000-0000-0000-000000000041', 'Delirium tremens typically develops 48-72 hours after the last drink and presents with autonomic hyperactivity, hallucinations, agitation and disorientation; it carries significant mortality if untreated and requires inpatient monitored benzodiazepine treatment.', 1),
('dc000000-0000-0000-0000-000000000041', $x$IV thiamine (Pabrinex) must be given before, or at minimum alongside, any glucose-containing fluids or food in patients at risk of thiamine deficiency, since glucose administration to a thiamine-deficient patient can precipitate or worsen Wernicke's encephalopathy.$x$, 2),
('dc000000-0000-0000-0000-000000000041', 'Benzodiazepines (e.g., chlordiazepoxide) are first-line for alcohol withdrawal and delirium tremens; antipsychotics do not treat the underlying withdrawal and are reserved as a cautious adjunct for severe, persistent psychotic symptoms.', 3),
('dc000000-0000-0000-0000-000000000042', 'Opioid toxicity classically presents with the triad of pinpoint pupils, respiratory depression and reduced consciousness; naloxone is the specific reversal agent, titrated to restore adequate ventilation.', 1),
('dc000000-0000-0000-0000-000000000042', 'Naloxone has a shorter duration of action than many opioids (particularly long-acting agents such as methadone), creating a risk of re-sedation and recurrent respiratory depression once naloxone wears off, necessitating a period of monitored observation after reversal.', 2),
('dc000000-0000-0000-0000-000000000042', 'Flumazenil is the reversal agent for benzodiazepine toxicity, not opioid toxicity, and should not be confused with naloxone; the two clinical pictures and their specific antidotes are distinct.', 3),
('dc000000-0000-0000-0000-000000000043', 'Buprenorphine (a partial opioid agonist) carries a substantially lower risk of QTc prolongation, respiratory depression and overdose compared with methadone, making it a preferable choice in patients with cardiac risk factors or baseline QTc prolongation.', 1),
('dc000000-0000-0000-0000-000000000043', 'Methadone is associated with dose-dependent QTc prolongation and torsades de pointes risk, requiring baseline and interval ECG monitoring, particularly in patients with other risk factors.', 2),
('dc000000-0000-0000-0000-000000000043', 'Opioid substitution therapy (with either buprenorphine or methadone) substantially reduces overdose and mortality risk compared with abrupt cessation or no treatment, by maintaining tolerance and reducing illicit opioid use; naltrexone requires prior abstinence and is not used to initiate treatment in actively dependent patients.', 3),
('dc000000-0000-0000-0000-000000000044', 'Flumazenil is generally avoided in benzodiazepine overdose (except in narrow, carefully selected circumstances) because of the significant risk of precipitating severe, potentially treatment-resistant seizures, especially in patients with epilepsy, benzodiazepine tolerance, or mixed/unknown co-ingestions.', 1),
('dc000000-0000-0000-0000-000000000044', 'Management of benzodiazepine/alcohol overdose with reduced consciousness centres on supportive care, especially airway protection and monitoring, rather than pharmacological reversal in most cases.', 2),
('dc000000-0000-0000-0000-000000000044', 'Naloxone is specific to opioid toxicity and should not be given reflexively for reduced consciousness without supporting clinical features (pinpoint pupils, respiratory depression, opioid history) suggesting opioid co-ingestion.', 3),
('dc000000-0000-0000-0000-000000000045', 'Cocaine-induced acute coronary syndrome results from coronary vasospasm and increased sympathetic drive; benzodiazepines (reducing central sympathetic outflow) and glyceryl trinitrate (vasodilation) are recommended adjuncts alongside standard ACS management.', 1),
('dc000000-0000-0000-0000-000000000045', 'Beta-blockers (including mixed alpha/beta agents like labetalol) should be avoided in the acute management of cocaine-associated chest pain due to the risk of unopposed alpha-adrenergic vasoconstriction worsening coronary spasm and hypertension.', 2),
('dc000000-0000-0000-0000-000000000045', 'Despite the drug-related trigger, cocaine-associated ST-elevation ACS with troponin rise is managed as a genuine, time-critical acute coronary syndrome requiring urgent cardiology involvement and standard antiplatelet/anticoagulant/reperfusion pathways, alongside the specific modifications above.', 3),
('dc000000-0000-0000-0000-000000000046', $x$The classic triad of Wernicke's encephalopathy is confusion, ataxia and ophthalmoplegia/nystagmus, though not all three features need be present for the diagnosis to be made and treated empirically.$x$, 1),
('dc000000-0000-0000-0000-000000000046', $x$Wernicke's encephalopathy requires urgent high-dose IV (parenteral) thiamine, given before or alongside any glucose administration, since glucose in a thiamine-deficient patient can precipitate or worsen the condition.$x$, 2),
('dc000000-0000-0000-0000-000000000046', $x$Inadequately or belatedly treated Wernicke's encephalopathy can progress to Korsakoff syndrome, characterised by largely irreversible anterograde and retrograde amnesia with confabulation — underscoring the urgency of prompt, adequate thiamine replacement.$x$, 3),
('dc000000-0000-0000-0000-000000000047', 'Standard urine drug immunoassays do not reliably detect novel psychoactive substances (e.g., synthetic cannabinoids, novel stimulants); a negative screen does not exclude their use, and clinical history and examination findings should guide management.', 1),
('dc000000-0000-0000-0000-000000000047', 'Toxicity from synthetic cannabinoids and many novel psychoactive substances typically produces a sympathomimetic toxidrome (tachycardia, hypertension, agitation, sweating, variable consciousness) managed supportively, as there is no specific antidote.', 2),
('dc000000-0000-0000-0000-000000000047', 'As with other sympathomimetic toxidromes (e.g., cocaine), beta-blockers are generally avoided due to the risk of unopposed alpha-adrenergic effects; benzodiazepines are preferred for controlling agitation and associated sympathetic overactivity.', 3),
('dc000000-0000-0000-0000-000000000048', 'GHB/GBL withdrawal is notable for its potential to progress extremely rapidly (sometimes within hours) from mild symptoms to severe agitation, delirium, autonomic instability and life-threatening complications, distinguishing it from the more gradual evolution typical of alcohol withdrawal.', 1),
('dc000000-0000-0000-0000-000000000048', 'Management of severe or rapidly escalating GHB/GBL withdrawal often requires higher benzodiazepine doses than standard alcohol withdrawal regimens, with a low threshold for monitored or high-dependency level care.', 2),
('dc000000-0000-0000-0000-000000000048', 'A history of previous severe or rapidly escalating withdrawal episodes is an important predictor of risk and should lower the threshold for early, assertive treatment and a higher level of monitoring in subsequent episodes.', 3),
('dc000000-0000-0000-0000-000000000049', 'Acamprosate reduces craving via glutamatergic/GABAergic mechanisms, is renally excreted (so dose adjustment/caution applies in renal, not hepatic, impairment), and does not carry the hepatotoxicity or dangerous alcohol-reaction risks of naltrexone or disulfiram respectively.', 1),
('dc000000-0000-0000-0000-000000000049', 'Disulfiram causes a severe, potentially dangerous reaction (flushing, tachycardia, hypotension, vomiting) if alcohol is consumed while taking it, requiring careful patient selection, informed consent, and is unsuitable for patients unwilling to accept this risk or without reliable supervision/adherence.', 2),
('dc000000-0000-0000-0000-000000000049', 'Naltrexone carries a risk of hepatotoxicity and requires caution and monitoring of liver function in patients with hepatic impairment, informing the choice of relapse-prevention agent in patients with pre-existing liver disease.', 3),
('dc000000-0000-0000-0000-000000000050', 'Stimulant (amphetamine/methamphetamine, cocaine)-induced psychosis typically presents with persecutory delusions and tactile/formication hallucinations (sensation of insects under the skin, often leading to skin picking/excoriations), agitation and sympathomimetic signs, usually with preserved orientation, distinguishing it from other causes of psychosis such as delirium.', 1),
('dc000000-0000-0000-0000-000000000050', 'Management is supportive (calm, low-stimulus environment), with benzodiazepines for agitation and short-term antipsychotic medication if psychotic symptoms are severe or persistent; symptoms often improve with abstinence and time.', 2),
('dc000000-0000-0000-0000-000000000050', 'As with other sympathomimetic toxidromes, beta-blockers should be avoided for associated tachycardia/hypertension due to the risk of unopposed alpha-adrenergic vasoconstriction.', 3);
